-- ==================== CURSOR ====================
UPDATE tools SET faq = '[{"q":"Что такое Cursor?","a":"Cursor — AI-нативная IDE на базе VS Code. AI получает полный контекст кодовой базы, редактирует несколько файлов, выполняет команды в терминале и завершает задачи автономно."},{"q":"Сколько стоит Cursor?","a":"Бесплатный план Hobby с ограниченными запросами. Pro — $20/месяц (500 быстрых запросов). Business — $40/пользователь/месяц с SSO."},{"q":"Безопасно ли использовать Cursor?","a":"Cursor предлагает режим приватности — код не хранится на серверах. Enterprise включает дополнительные средства защиты данных и соответствие SOC 2."},{"q":"Какие модели использует Cursor?","a":"Cursor использует Claude Opus 4.7, GPT-4o и собственные fine-tuned модели для автодополнения. Модель можно переключать в настройках."}]'::jsonb WHERE slug = 'cursor' AND lang = 'ru';

UPDATE tools SET faq = '[{"q":"¿Qué es Cursor?","a":"Cursor es un IDE nativo de IA basado en VS Code. Le da al AI contexto completo de tu base de código y puede editar múltiples archivos, ejecutar comandos y completar tareas de principio a fin como agente."},{"q":"¿Cuánto cuesta Cursor?","a":"Plan Hobby gratuito con solicitudes limitadas. Pro es $20/mes (500 solicitudes rápidas). Business es $40/usuario/mes con SSO y funciones de equipo."},{"q":"¿Es seguro usar Cursor?","a":"Cursor ofrece un Modo de Privacidad que deshabilita el almacenamiento de código en sus servidores. Los planes Enterprise incluyen controles adicionales y conformidad SOC 2."},{"q":"¿Qué modelos usa Cursor?","a":"Cursor usa Claude Opus 4.7, GPT-4o y modelos fine-tuned propios para autocompletado. Puedes cambiar modelos por solicitud en la configuración."}]'::jsonb WHERE slug = 'cursor' AND lang = 'es';

UPDATE tools SET faq = '[{"q":"Was ist Cursor?","a":"Cursor ist eine KI-native IDE auf Basis von VS Code. Die KI bekommt vollen Kontext deiner Codebasis, kann mehrere Dateien bearbeiten, Terminal-Befehle ausführen und Aufgaben autonom erledigen."},{"q":"Was kostet Cursor?","a":"Kostenloser Hobby-Plan mit begrenzten Anfragen. Pro kostet $20/Monat (500 schnelle Anfragen). Business kostet $40/Nutzer/Monat mit SSO und Team-Funktionen."},{"q":"Ist Cursor sicher für meinen Code?","a":"Cursor bietet einen Datenschutzmodus, der die Code-Speicherung auf ihren Servern deaktiviert. Enterprise-Pläne umfassen zusätzliche Datenkontrolle und SOC 2-Konformität."},{"q":"Welche Modelle verwendet Cursor?","a":"Cursor verwendet Claude Opus 4.7, GPT-4o und eigene fine-tuned Modelle für die Autovervollständigung. Das Modell kann pro Anfrage in den Einstellungen gewechselt werden."}]'::jsonb WHERE slug = 'cursor' AND lang = 'de';

UPDATE tools SET faq = '[{"q":"Що таке Cursor?","a":"Cursor — AI-нативна IDE на базі VS Code. AI отримує повний контекст кодової бази, редагує кілька файлів, виконує команди в терміналі та виконує завдання автономно."},{"q":"Скільки коштує Cursor?","a":"Безкоштовний план Hobby з обмеженими запитами. Pro — $20/місяць (500 швидких запитів). Business — $40/користувач/місяць з SSO."},{"q":"Чи безпечно використовувати Cursor?","a":"Cursor пропонує режим приватності — код не зберігається на серверах. Enterprise включає додаткові засоби захисту даних та відповідність SOC 2."},{"q":"Які моделі використовує Cursor?","a":"Cursor використовує Claude Opus 4.7, GPT-4o та власні fine-tuned моделі для автодоповнення. Модель можна перемикати в налаштуваннях."}]'::jsonb WHERE slug = 'cursor' AND lang = 'ua';

UPDATE tools SET faq = '[{"q":"מה זה Cursor?","a":"Cursor הוא IDE מבוסס AI שנבנה על VS Code. ה-AI מקבל הקשר מלא של קוד הפרויקט, יכול לערוך מספר קבצים, להריץ פקודות טרמינל ולהשלים משימות באופן אוטונומי."},{"q":"כמה עולה Cursor?","a":"תוכנית Hobby חינמית עם בקשות מוגבלות. Pro עולה $20 לחודש (500 בקשות מהירות). Business עולה $40 למשתמש לחודש עם SSO."},{"q":"האם Cursor בטוח לשימוש?","a":"Cursor מציע מצב פרטיות שמשבית שמירת קוד על השרתים שלהם. תוכניות Enterprise כוללות בקרות נתונים נוספות ועמידה בתקן SOC 2."},{"q":"אילו מודלים משתמש Cursor?","a":"Cursor משתמש ב-Claude Opus 4.7, GPT-4o ומודלים fine-tuned משלו להשלמה אוטומטית. ניתן לעבור בין מודלים לפי בקשה בהגדרות."}]'::jsonb WHERE slug = 'cursor' AND lang = 'he';

UPDATE tools SET faq = '[{"q":"Qu''est-ce que Cursor ?","a":"Cursor est un IDE natif IA basé sur VS Code. Il donne à l''IA un contexte complet de votre base de code, peut modifier plusieurs fichiers, exécuter des commandes terminal et accomplir des tâches de bout en bout comme un agent."},{"q":"Combien coûte Cursor ?","a":"Plan Hobby gratuit avec requêtes limitées. Pro à $20/mois (500 requêtes rapides). Business à $40/utilisateur/mois avec SSO et fonctionnalités d''équipe."},{"q":"Cursor est-il sûr pour mon code ?","a":"Cursor propose un Mode Confidentialité qui désactive le stockage du code sur leurs serveurs. Les plans Enterprise incluent des contrôles de données supplémentaires et la conformité SOC 2."},{"q":"Quels modèles utilise Cursor ?","a":"Cursor utilise Claude Opus 4.7, GPT-4o et ses propres modèles fine-tuned pour l''autocomplétion. Vous pouvez changer de modèle par requête dans les paramètres."}]'::jsonb WHERE slug = 'cursor' AND lang = 'fr';

UPDATE tools SET faq = '[{"q":"O que é o Cursor?","a":"O Cursor é um IDE nativo de IA baseado no VS Code. Ele dá à IA contexto completo da sua base de código, pode editar múltiplos arquivos, executar comandos no terminal e completar tarefas do início ao fim como um agente."},{"q":"Quanto custa o Cursor?","a":"Plano Hobby gratuito com solicitações limitadas. Pro custa $20/mês (500 solicitações rápidas). Business custa $40/usuário/mês com SSO e recursos de equipe."},{"q":"O Cursor é seguro para meu código?","a":"O Cursor oferece um Modo de Privacidade que desativa o armazenamento de código em seus servidores. Os planos Enterprise incluem controles de dados adicionais e conformidade com SOC 2."},{"q":"Quais modelos o Cursor usa?","a":"O Cursor usa Claude Opus 4.7, GPT-4o e seus próprios modelos fine-tuned para autocompletar. Você pode mudar de modelo por solicitação nas configurações."}]'::jsonb WHERE slug = 'cursor' AND lang = 'pt';

