UPDATE tools SET faq = '[{"q":"Что такое Bolt.new?","a":"Bolt.new — браузерный AI-конструктор полного стека от StackBlitz. Опишите что хотите создать — и получите готовое веб-приложение с фронтендом, бэкендом и базой данных, работающее прямо в браузере."},{"q":"Сколько стоит Bolt.new?","a":"Бесплатный тариф с ограниченными токенами. Pro — $20/месяц. Командные планы доступны для совместной работы."},{"q":"Может ли Bolt.new задеплоить приложение?","a":"Да. Bolt.new включает хостинг через StackBlitz. Публикация происходит мгновенно без настройки отдельного хостинга."},{"q":"Какой технологический стек использует Bolt.new?","a":"Bolt.new поддерживает React, Next.js, Vue, Svelte и другие популярные фреймворки. Интегрируется с Supabase для баз данных и сторонними API."}]'::jsonb WHERE slug = 'bolt-new' AND lang = 'ru';

UPDATE tools SET faq = '[{"q":"¿Qué es Bolt.new?","a":"Bolt.new es un constructor full-stack de IA en el navegador de StackBlitz. Describe lo que quieres crear y obtendrás una aplicación web completa con frontend, backend y base de datos, ejecutándose en vivo en el navegador."},{"q":"¿Cuánto cuesta Bolt.new?","a":"Nivel gratuito con tokens limitados. Pro es $20/mes. Planes de equipo disponibles para proyectos colaborativos."},{"q":"¿Puede Bolt.new desplegar mi app?","a":"Sí. Bolt.new incluye hosting propio a través de StackBlitz. Puedes publicar tu app instantáneamente sin configurar un proveedor de hosting separado."},{"q":"¿Qué stack tecnológico usa Bolt.new?","a":"Bolt.new soporta React, Next.js, Vue, Svelte y otros frameworks populares. Se conecta a Supabase para bases de datos y puede integrarse con APIs de terceros."}]'::jsonb WHERE slug = 'bolt-new' AND lang = 'es';

UPDATE tools SET faq = '[{"q":"Was ist Bolt.new?","a":"Bolt.new ist ein browserbasierter KI-Full-Stack-Builder von StackBlitz. Beschreibe was du bauen möchtest und erhalte eine komplette Web-App mit Frontend, Backend und Datenbank, die live im Browser läuft."},{"q":"Was kostet Bolt.new?","a":"Kostenloses Kontingent mit begrenzten Tokens. Pro kostet $20/Monat. Team-Pläne für kollaborative Projekte verfügbar."},{"q":"Kann Bolt.new meine App deployen?","a":"Ja. Bolt.new enthält eigenes Hosting über StackBlitz. Deine App kann sofort veröffentlicht werden, ohne einen separaten Hosting-Anbieter zu konfigurieren."},{"q":"Welchen Tech-Stack verwendet Bolt.new?","a":"Bolt.new unterstützt React, Next.js, Vue, Svelte und andere populäre Frameworks. Es verbindet sich mit Supabase für Datenbanken und kann Drittanbieter-APIs integrieren."}]'::jsonb WHERE slug = 'bolt-new' AND lang = 'de';

UPDATE tools SET faq = '[{"q":"Що таке Bolt.new?","a":"Bolt.new — браузерний AI-конструктор повного стеку від StackBlitz. Опишіть що хочете створити — і отримаєте готовий вебдодаток з фронтендом, бекендом і базою даних, що працює прямо в браузері."},{"q":"Скільки коштує Bolt.new?","a":"Безкоштовний рівень з обмеженими токенами. Pro — $20/місяць. Командні плани доступні для спільної роботи."},{"q":"Чи може Bolt.new задеплоїти додаток?","a":"Так. Bolt.new включає хостинг через StackBlitz. Публікація відбувається миттєво без налаштування окремого хостингу."},{"q":"Який технологічний стек використовує Bolt.new?","a":"Bolt.new підтримує React, Next.js, Vue, Svelte та інші популярні фреймворки. Інтегрується з Supabase для баз даних та сторонніми API."}]'::jsonb WHERE slug = 'bolt-new' AND lang = 'ua';

UPDATE tools SET faq = '[{"q":"מה זה Bolt.new?","a":"Bolt.new הוא בונה full-stack מבוסס AI בדפדפן מ-StackBlitz. תאר מה שאתה רוצה לבנות וקבל אפליקציית ווב מלאה עם frontend, backend ובסיס נתונים, שרצה ישירות בדפדפן."},{"q":"כמה עולה Bolt.new?","a":"רמה חינמית עם טוקנים מוגבלים. Pro עולה $20 לחודש. תוכניות צוות זמינות לפרויקטים שיתופיים."},{"q":"האם Bolt.new יכול לפרוס את האפליקציה שלי?","a":"כן. Bolt.new כולל אירוח מובנה דרך StackBlitz. ניתן לפרסם את האפליקציה מיידית ללא הגדרת ספק אירוח נפרד."},{"q":"איזה סטאק טכנולוגי משתמש Bolt.new?","a":"Bolt.new תומך ב-React, Next.js, Vue, Svelte ופריימוורקים פופולריים נוספים. מתחבר ל-Supabase לבסיסי נתונים ויכול לשלב APIs של צד שלישי."}]'::jsonb WHERE slug = 'bolt-new' AND lang = 'he';

UPDATE tools SET faq = '[{"q":"Qu''est-ce que Bolt.new ?","a":"Bolt.new est un constructeur full-stack IA dans le navigateur par StackBlitz. Décrivez ce que vous voulez créer et obtenez une application web complète avec frontend, backend et base de données, fonctionnant en direct dans le navigateur."},{"q":"Combien coûte Bolt.new ?","a":"Niveau gratuit avec tokens limités. Pro à $20/mois. Plans équipe disponibles pour les projets collaboratifs."},{"q":"Bolt.new peut-il déployer mon application ?","a":"Oui. Bolt.new inclut un hébergement intégré via StackBlitz. Vous pouvez publier votre app instantanément sans configurer un hébergeur séparé."},{"q":"Quel stack technologique utilise Bolt.new ?","a":"Bolt.new supporte React, Next.js, Vue, Svelte et d''autres frameworks populaires. Il se connecte à Supabase pour les bases de données et peut intégrer des API tierces."}]'::jsonb WHERE slug = 'bolt-new' AND lang = 'fr';

UPDATE tools SET faq = '[{"q":"O que é o Bolt.new?","a":"O Bolt.new é um construtor full-stack de IA no navegador da StackBlitz. Descreva o que quer criar e obtenha um aplicativo web completo com frontend, backend e banco de dados, rodando ao vivo no navegador."},{"q":"Quanto custa o Bolt.new?","a":"Nível gratuito com tokens limitados. Pro custa $20/mês. Planos de equipe disponíveis para projetos colaborativos."},{"q":"O Bolt.new pode fazer o deploy do meu app?","a":"Sim. O Bolt.new inclui hospedagem integrada via StackBlitz. Você pode publicar seu app instantaneamente sem configurar um provedor de hospedagem separado."},{"q":"Qual stack tecnológico o Bolt.new usa?","a":"O Bolt.new suporta React, Next.js, Vue, Svelte e outros frameworks populares. Conecta-se ao Supabase para bancos de dados e pode integrar APIs de terceiros."}]'::jsonb WHERE slug = 'bolt-new' AND lang = 'pt';

-- ==================== MANUS ====================
UPDATE tools SET faq = '[{"q":"Что такое Manus?","a":"Manus — автономный AI-агент от Monica.im, который самостоятельно выполняет сложные задачи: просматривает веб, пишет и запускает код, управляет файлами и заполняет формы без пошаговых инструкций."},{"q":"Сколько стоит Manus?","a":"Manus находится в закрытой бете по приглашениям. Список ожидания доступен на manus.im. Цены для широкого релиза не объявлены."},{"q":"Что Manus умеет делать автономно?","a":"Manus может исследовать темы в интернете, писать и запускать код, управлять таблицами, заполнять формы, создавать мобильные и веб-приложения — всё из одной высокоуровневой инструкции."},{"q":"Чем Manus отличается от других AI-агентов?","a":"Manus работает в постоянной рабочей среде, похожей на рабочий стол: открывает браузеры, запускает терминалы, управляет файлами. Большинство агентов только генерируют текст — Manus реально выполняет задачи."}]'::jsonb WHERE slug = 'manus' AND lang = 'ru';

UPDATE tools SET faq = '[{"q":"¿Qué es Manus?","a":"Manus es un agente de IA autónomo de Monica.im que puede completar tareas complejas de forma independiente: navegar por la web, escribir y ejecutar código, gestionar archivos y rellenar formularios sin instrucciones paso a paso."},{"q":"¿Cuánto cuesta Manus?","a":"Manus está actualmente en beta solo por invitación. Una lista de espera está disponible en manus.im. Los precios para el lanzamiento general no han sido anunciados."},{"q":"¿Qué puede hacer Manus de forma autónoma?","a":"Manus puede investigar temas en la web, escribir y ejecutar código, gestionar hojas de cálculo, rellenar formularios, crear apps móviles y web, todo desde una sola instrucción de alto nivel."},{"q":"¿En qué se diferencia Manus de otros agentes de IA?","a":"Manus opera con un entorno persistente similar a un escritorio: puede abrir navegadores, ejecutar terminales y gestionar archivos como un asistente humano. La mayoría de agentes solo generan texto; Manus realmente ejecuta tareas."}]'::jsonb WHERE slug = 'manus' AND lang = 'es';

UPDATE tools SET faq = '[{"q":"Was ist Manus?","a":"Manus ist ein autonomer KI-Agent von Monica.im, der komplexe Aufgaben selbstständig erledigt: im Web surfen, Code schreiben und ausführen, Dateien verwalten und Formulare ausfüllen — ohne Schritt-für-Schritt-Anleitung."},{"q":"Was kostet Manus?","a":"Manus befindet sich derzeit in einer geschlossenen Beta per Einladung. Eine Warteliste ist auf manus.im verfügbar. Preise für den allgemeinen Release wurden noch nicht bekanntgegeben."},{"q":"Was kann Manus autonom tun?","a":"Manus kann Themen im Web recherchieren, Code schreiben und ausführen, Tabellen verwalten, Formulare ausfüllen und Mobile- sowie Web-Apps erstellen — alles aus einer einzigen übergeordneten Anweisung."},{"q":"Wie unterscheidet sich Manus von anderen KI-Agenten?","a":"Manus arbeitet in einer persistenten Desktop-ähnlichen Umgebung — es kann Browser öffnen, Terminals ausführen und Dateien verwalten wie ein menschlicher Assistent. Die meisten Agenten generieren nur Text; Manus führt Aufgaben tatsächlich aus."}]'::jsonb WHERE slug = 'manus' AND lang = 'de';

UPDATE tools SET faq = '[{"q":"Що таке Manus?","a":"Manus — автономний AI-агент від Monica.im, який самостійно виконує складні завдання: переглядає веб, пише та запускає код, керує файлами і заповнює форми без покрокових інструкцій."},{"q":"Скільки коштує Manus?","a":"Manus знаходиться у закритій беті за запрошеннями. Список очікування доступний на manus.im. Ціни для широкого релізу не оголошені."},{"q":"Що Manus вміє робити автономно?","a":"Manus може досліджувати теми в інтернеті, писати та запускати код, керувати таблицями, заповнювати форми, створювати мобільні та вебдодатки — все з однієї високорівневої інструкції."},{"q":"Чим Manus відрізняється від інших AI-агентів?","a":"Manus працює в постійному робочому середовищі, схожому на робочий стіл: відкриває браузери, запускає термінали, керує файлами. Більшість агентів лише генерують текст — Manus реально виконує завдання."}]'::jsonb WHERE slug = 'manus' AND lang = 'ua';

UPDATE tools SET faq = '[{"q":"מה זה Manus?","a":"Manus הוא סוכן AI אוטונומי מ-Monica.im שיכול להשלים משימות מורכבות באופן עצמאי: גלישה באינטרנט, כתיבה והרצת קוד, ניהול קבצים ומילוי טפסים ללא הוראות שלב-אחר-שלב."},{"q":"כמה עולה Manus?","a":"Manus נמצא כרגע בבטא סגורה על פי הזמנה. רשימת המתנה זמינה ב-manus.im. מחירים להשקה הכללית טרם הוכרזו."},{"q":"מה Manus יכול לעשות באופן אוטונומי?","a":"Manus יכול לחקור נושאים באינטרנט, לכתוב ולהריץ קוד, לנהל גיליונות אלקטרוניים, למלא טפסים וליצור אפליקציות מובייל ווב — הכל מהוראה אחת ברמה גבוהה."},{"q":"במה Manus שונה מסוכני AI אחרים?","a":"Manus פועל בסביבת עבודה מתמשכת דמוית שולחן עבודה — הוא יכול לפתוח דפדפנים, להריץ טרמינלים ולנהל קבצים כמו עוזר אנושי. רוב הסוכנים רק מייצרים טקסט; Manus ממש מבצע משימות."}]'::jsonb WHERE slug = 'manus' AND lang = 'he';

UPDATE tools SET faq = '[{"q":"Qu''est-ce que Manus ?","a":"Manus est un agent IA autonome de Monica.im qui peut accomplir des tâches complexes de manière indépendante : naviguer sur le web, écrire et exécuter du code, gérer des fichiers et remplir des formulaires sans instructions étape par étape."},{"q":"Combien coûte Manus ?","a":"Manus est actuellement en bêta fermée sur invitation. Une liste d''attente est disponible sur manus.im. Les tarifs pour la sortie générale n''ont pas encore été annoncés."},{"q":"Que peut faire Manus de manière autonome ?","a":"Manus peut rechercher des sujets sur le web, écrire et exécuter du code, gérer des feuilles de calcul, remplir des formulaires et créer des applications mobiles et web — le tout depuis une seule instruction de haut niveau."},{"q":"En quoi Manus diffère-t-il des autres agents IA ?","a":"Manus fonctionne avec un environnement de bureau persistant — il peut ouvrir des navigateurs, exécuter des terminaux et gérer des fichiers comme un assistant humain. La plupart des agents ne font que générer du texte ; Manus exécute réellement les tâches."}]'::jsonb WHERE slug = 'manus' AND lang = 'fr';

UPDATE tools SET faq = '[{"q":"O que é o Manus?","a":"O Manus é um agente de IA autônomo da Monica.im que pode completar tarefas complexas de forma independente: navegar na web, escrever e executar código, gerenciar arquivos e preencher formulários sem instruções passo a passo."},{"q":"Quanto custa o Manus?","a":"O Manus está atualmente em beta fechado por convite. Uma lista de espera está disponível em manus.im. Os preços para o lançamento geral ainda não foram anunciados."},{"q":"O que o Manus pode fazer de forma autônoma?","a":"O Manus pode pesquisar tópicos na web, escrever e executar código, gerenciar planilhas, preencher formulários e criar apps mobile e web — tudo a partir de uma única instrução de alto nível."},{"q":"Como o Manus se diferencia de outros agentes de IA?","a":"O Manus opera com um ambiente persistente semelhante a um desktop — pode abrir navegadores, executar terminais e gerenciar arquivos como um assistente humano. A maioria dos agentes apenas gera texto; o Manus realmente executa tarefas."}]'::jsonb WHERE slug = 'manus' AND lang = 'pt';

-- ==================== MURF AI (ru/es/de only — ua/he/fr/pt = full INSERT below) ====================
UPDATE tools SET faq = '[{"q":"Что такое Murf AI?","a":"Murf AI — профессиональный AI-генератор голоса для создания озвучки. Предлагает 200+ голосов на 20+ языках, студийное качество для e-learning, объясняющих видео, презентаций и рекламы."},{"q":"Сколько стоит Murf AI?","a":"Бесплатный план — 10 минут генерации. Creator — $29/месяц, Business — $99/месяц, Enterprise — по запросу. Годовой план даёт скидку ~33%."},{"q":"Чем Murf AI отличается от ElevenLabs?","a":"Murf AI — это полная студия озвучки: редактор скриптов, синхронизация со слайдами, музыка. ElevenLabs фокусируется на клонировании голоса, голосовых агентах и доступе через API для разработчиков."},{"q":"Поддерживает ли Murf AI клонирование голоса?","a":"Да. Клонирование голоса доступно на планах Business и Enterprise, позволяя командам создавать фирменные голоса для всего контента."}]'::jsonb WHERE slug = 'murf-ai' AND lang = 'ru';

UPDATE tools SET faq = '[{"q":"¿Qué es Murf AI?","a":"Murf AI es un generador de voz profesional de IA para crear voiceovers. Ofrece más de 200 voces en 20+ idiomas con calidad de estudio para e-learning, videos explicativos, presentaciones y anuncios."},{"q":"¿Cuánto cuesta Murf AI?","a":"Plan gratuito con 10 minutos de generación. Creator es $29/mes, Business es $99/mes, Enterprise es precio personalizado. La facturación anual da ~33% de descuento."},{"q":"¿En qué se diferencia Murf AI de ElevenLabs?","a":"Murf AI es un estudio completo de producción de voz: editor de guiones, sincronización de diapositivas, música. ElevenLabs se centra en clonación de voz, agentes de voz en tiempo real y acceso API para desarrolladores."},{"q":"¿Admite Murf AI la clonación de voz?","a":"Sí. La clonación de voz está disponible en los planes Business y Enterprise, permitiendo a los equipos crear voces de marca consistentes en todo su contenido."}]'::jsonb WHERE slug = 'murf-ai' AND lang = 'es';

UPDATE tools SET faq = '[{"q":"Was ist Murf AI?","a":"Murf AI ist ein professioneller KI-Stimmgenerator für Voiceovers. Er bietet 200+ Stimmen in 20+ Sprachen in Studioqualität für E-Learning, Erklärvideos, Präsentationen und Werbung."},{"q":"Was kostet Murf AI?","a":"Kostenloser Plan mit 10 Minuten Generierung. Creator kostet $29/Monat, Business $99/Monat, Enterprise auf Anfrage. Jahresabrechnung spart ~33%."},{"q":"Wie unterscheidet sich Murf AI von ElevenLabs?","a":"Murf AI ist ein vollständiges Voiceover-Studio: Skript-Editor, Folien-Synchronisation, Musik. ElevenLabs fokussiert sich auf Stimmklonen, Echtzeit-Sprach-Agenten und Entwickler-API-Zugang."},{"q":"Unterstützt Murf AI das Klonen von Stimmen?","a":"Ja. Stimmklonen ist in Business- und Enterprise-Plänen verfügbar, sodass Teams markenkonsistente Stimmen für alle Inhalte erstellen können."}]'::jsonb WHERE slug = 'murf-ai' AND lang = 'de';

-- ==================== PLAYHT ====================
UPDATE tools SET faq = '[{"q":"Что такое PlayHT?","a":"PlayHT — AI-платформа text-to-speech с 900+ голосами на 142 языках. Используется для подкастов, аудиокниг, статей и приложений с поддержкой клонирования голоса и API для разработчиков."},{"q":"Сколько стоит PlayHT?","a":"Creator — $31/месяц (100K слов), Unlimited — $99/месяц, Enterprise — по запросу. Годовой план со скидками."},{"q":"Чем PlayHT отличается от ElevenLabs?","a":"PlayHT имеет более широкую библиотеку голосов и сильные воркфлоу для подкастов и нарратива статей. ElevenLabs лидирует в голосовых агентах реального времени, потоковой передаче с низкой задержкой и инструментах для разработчиков."},{"q":"Поддерживает ли PlayHT клонирование голоса?","a":"Да. Мгновенное клонирование голоса из короткого аудиосэмпла доступно на планах Creator и выше. Клонированные голоса можно использовать неограниченно в рамках плана."}]'::jsonb WHERE slug = 'playht' AND lang = 'ru';

UPDATE tools SET faq = '[{"q":"¿Qué es PlayHT?","a":"PlayHT es una plataforma de texto a voz con IA con más de 900 voces en 142 idiomas. Se usa para podcasts, audiolibros, artículos y apps, con clonación de voz y API para desarrolladores."},{"q":"¿Cuánto cuesta PlayHT?","a":"Creator es $31/mes (100K palabras), Unlimited es $99/mes, Enterprise es precio personalizado. Descuentos con facturación anual."},{"q":"¿En qué se diferencia PlayHT de ElevenLabs?","a":"PlayHT tiene una biblioteca de voces más amplia y mejores flujos de trabajo para podcasts y narración de artículos. ElevenLabs lidera en agentes de voz en tiempo real, streaming de baja latencia y herramientas para desarrolladores."},{"q":"¿Admite PlayHT la clonación de voz?","a":"Sí. La clonación de voz instantánea desde una muestra de audio corta está disponible en el plan Creator y superiores. Las voces clonadas se pueden usar ilimitadamente dentro de tu plan."}]'::jsonb WHERE slug = 'playht' AND lang = 'es';

UPDATE tools SET faq = '[{"q":"Was ist PlayHT?","a":"PlayHT ist eine KI-Text-to-Speech-Plattform mit 900+ Stimmen in 142 Sprachen. Es wird für Podcasts, Hörbücher, Artikel und Apps verwendet, mit Stimmklonen und Entwickler-API."},{"q":"Was kostet PlayHT?","a":"Creator kostet $31/Monat (100K Wörter), Unlimited $99/Monat, Enterprise auf Anfrage. Rabatte bei Jahresabrechnung."},{"q":"Wie unterscheidet sich PlayHT von ElevenLabs?","a":"PlayHT hat eine größere Stimmbibliothek und stärkere Podcast- und Artikel-Narrations-Workflows. ElevenLabs führt bei Echtzeit-Sprach-Agenten, Niedriglatenz-Streaming und Entwicklertools."},{"q":"Unterstützt PlayHT das Klonen von Stimmen?","a":"Ja. Sofortiges Stimmklonen aus einer kurzen Audioaufnahme ist ab dem Creator-Plan verfügbar. Geklonte Stimmen können unbegrenzt innerhalb des Plans verwendet werden."}]'::jsonb WHERE slug = 'playht' AND lang = 'de';

UPDATE tools SET faq = '[{"q":"Що таке PlayHT?","a":"PlayHT — AI-платформа text-to-speech з 900+ голосами на 142 мовах. Використовується для подкастів, аудіокниг, статей і додатків з підтримкою клонування голосу та API для розробників."},{"q":"Скільки коштує PlayHT?","a":"Creator — $31/місяць (100K слів), Unlimited — $99/місяць, Enterprise — за запитом. Річний план зі знижками."},{"q":"Чим PlayHT відрізняється від ElevenLabs?","a":"PlayHT має ширшу бібліотеку голосів і сильні воркфлоу для подкастів і нарративу статей. ElevenLabs лідирує в голосових агентах реального часу, стримінгу з низькою затримкою та інструментах для розробників."},{"q":"Чи підтримує PlayHT клонування голосу?","a":"Так. Миттєве клонування голосу з короткого аудіосемплу доступне на планах Creator і вище. Клоновані голоси можна використовувати необмежено в рамках плану."}]'::jsonb WHERE slug = 'playht' AND lang = 'ua';

UPDATE tools SET faq = '[{"q":"מה זה PlayHT?","a":"PlayHT היא פלטפורמת text-to-speech מבוססת AI עם 900+ קולות ב-142 שפות. משמשת לפודקאסטים, ספרי שמע, מאמרים ואפליקציות, עם שיבוט קול ו-API למפתחים."},{"q":"כמה עולה PlayHT?","a":"Creator עולה $31 לחודש (100K מילים), Unlimited עולה $99 לחודש, Enterprise במחיר מותאם. הנחות עם חיוב שנתי."},{"q":"במה PlayHT שונה מ-ElevenLabs?","a":"ל-PlayHT יש ספריית קולות גדולה יותר וזרימות עבודה חזקות לפודקאסטים ונארציה של מאמרים. ElevenLabs מוביל בסוכני קול בזמן אמת, סטרימינג עם זמן אחזור נמוך וכלים למפתחים."},{"q":"האם PlayHT תומך בשיבוט קול?","a":"כן. שיבוט קול מיידי מדגימת שמע קצרה זמין בתוכנית Creator ומעלה. קולות משובטים ניתן להשתמש בהם ללא הגבלה בתוך התוכנית."}]'::jsonb WHERE slug = 'playht' AND lang = 'he';

UPDATE tools SET faq = '[{"q":"Qu''est-ce que PlayHT ?","a":"PlayHT est une plateforme de synthèse vocale IA avec plus de 900 voix dans 142 langues. Utilisée pour les podcasts, livres audio, articles et applications, avec clonage vocal et API développeur."},{"q":"Combien coûte PlayHT ?","a":"Creator à $31/mois (100K mots), Unlimited à $99/mois, Enterprise sur devis. Réductions avec facturation annuelle."},{"q":"En quoi PlayHT diffère-t-il d''ElevenLabs ?","a":"PlayHT dispose d''une bibliothèque de voix plus grande et de meilleurs workflows pour les podcasts et la narration d''articles. ElevenLabs est leader sur les agents vocaux en temps réel, le streaming basse latence et les outils développeurs."},{"q":"PlayHT prend-il en charge le clonage vocal ?","a":"Oui. Le clonage vocal instantané à partir d''un court échantillon audio est disponible à partir du plan Creator. Les voix clonées peuvent être utilisées sans limite dans votre plan."}]'::jsonb WHERE slug = 'playht' AND lang = 'fr';

UPDATE tools SET faq = '[{"q":"O que é o PlayHT?","a":"O PlayHT é uma plataforma de text-to-speech com IA com mais de 900 vozes em 142 idiomas. Usado para podcasts, audiolivros, artigos e apps, com clonagem de voz e API para desenvolvedores."},{"q":"Quanto custa o PlayHT?","a":"Creator custa $31/mês (100K palavras), Unlimited custa $99/mês, Enterprise sob consulta. Descontos com cobrança anual."},{"q":"Como o PlayHT se diferencia do ElevenLabs?","a":"O PlayHT tem uma biblioteca de vozes maior e workflows mais fortes para podcasts e narração de artigos. O ElevenLabs lidera em agentes de voz em tempo real, streaming de baixa latência e ferramentas para desenvolvedores."},{"q":"O PlayHT suporta clonagem de voz?","a":"Sim. Clonagem de voz instantânea a partir de uma amostra de áudio curta está disponível no plano Creator e acima. Vozes clonadas podem ser usadas ilimitadamente dentro do seu plano."}]'::jsonb WHERE slug = 'playht' AND lang = 'pt';

-- ==================== NOTION AI ====================
UPDATE tools SET faq = '[{"q":"Что такое Notion AI?","a":"Notion AI — AI-ассистент, встроенный напрямую в Notion. Пишет, суммирует, переводит и отвечает на вопросы, используя содержимое вашего воркспейса как контекст."},{"q":"Сколько стоит Notion AI?","a":"Notion AI — дополнение за $10/участник/месяц (при годовой оплате) к любому плану Notion. Включён в планы Plus, Business и Enterprise с 2026 года."},{"q":"Что такое Notion Developer Platform 3.5?","a":"Notion Developer Platform 3.5 (май 2026) добавляет Workers runtime для серверлесс-функций, Sync API для данных в реальном времени и Webhooks для событийной автоматизации — превращая Notion в программируемую платформу."},{"q":"Может ли Notion AI работать с интернетом?","a":"Notion AI отвечает на вопросы из вашего воркспейса. Для данных в реальном времени используются подключённые интеграции, а не прямой браузинг интернета."}]'::jsonb WHERE slug = 'notion-ai' AND lang = 'ru';

UPDATE tools SET faq = '[{"q":"¿Qué es Notion AI?","a":"Notion AI es un asistente de IA integrado directamente en Notion. Puede escribir, resumir, traducir y responder preguntas usando el contenido de tu espacio de trabajo como contexto."},{"q":"¿Cuánto cuesta Notion AI?","a":"Notion AI es un complemento a $10/miembro/mes (facturación anual) en cualquier plan de Notion. Incluido en los planes Plus, Business y Enterprise desde 2026."},{"q":"¿Qué es Notion Developer Platform 3.5?","a":"Notion Developer Platform 3.5 (mayo 2026) añade Workers runtime para funciones serverless, Sync API para datos en tiempo real y Webhooks para automatización basada en eventos, convirtiendo Notion en una plataforma programable."},{"q":"¿Puede Notion AI acceder a internet?","a":"Notion AI responde preguntas usando el contenido de tu espacio de trabajo. Para datos en tiempo real, usa integraciones conectadas en lugar de navegar directamente por internet."}]'::jsonb WHERE slug = 'notion-ai' AND lang = 'es';

UPDATE tools SET faq = '[{"q":"Was ist Notion AI?","a":"Notion AI ist ein KI-Assistent, der direkt in Notion integriert ist. Er kann schreiben, zusammenfassen, übersetzen und Fragen beantworten, wobei der Inhalt deines Arbeitsbereichs als Kontext dient."},{"q":"Was kostet Notion AI?","a":"Notion AI ist ein Add-on für $10/Mitglied/Monat (Jahresabrechnung) zu jedem Notion-Plan. Ab 2026 in Plus-, Business- und Enterprise-Plänen enthalten."},{"q":"Was ist Notion Developer Platform 3.5?","a":"Notion Developer Platform 3.5 (Mai 2026) fügt Workers Runtime für serverlose Funktionen, Sync API für Echtzeit-Daten und Webhooks für ereignisgesteuerte Automatisierung hinzu — und macht Notion zu einer programmierbaren Plattform."},{"q":"Kann Notion AI auf das Internet zugreifen?","a":"Notion AI beantwortet Fragen aus dem Inhalt deines Arbeitsbereichs. Für Echtzeit-Webdaten werden verbundene Integrationen verwendet, kein direktes Internet-Browsen."}]'::jsonb WHERE slug = 'notion-ai' AND lang = 'de';

UPDATE tools SET faq = '[{"q":"Що таке Notion AI?","a":"Notion AI — AI-асистент, вбудований безпосередньо в Notion. Пише, підсумовує, перекладає і відповідає на запитання, використовуючи вміст вашого воркспейсу як контекст."},{"q":"Скільки коштує Notion AI?","a":"Notion AI — доповнення за $10/учасник/місяць (при річній оплаті) до будь-якого плану Notion. Включений у плани Plus, Business і Enterprise з 2026 року."},{"q":"Що таке Notion Developer Platform 3.5?","a":"Notion Developer Platform 3.5 (травень 2026) додає Workers runtime для серверлесс-функцій, Sync API для даних у реальному часі та Webhooks для подієвої автоматизації — перетворюючи Notion на програмовану платформу."},{"q":"Чи може Notion AI працювати з інтернетом?","a":"Notion AI відповідає на запитання з вашого воркспейсу. Для даних у реальному часі використовуються підключені інтеграції, а не прямий браузинг інтернету."}]'::jsonb WHERE slug = 'notion-ai' AND lang = 'ua';

UPDATE tools SET faq = '[{"q":"מה זה Notion AI?","a":"Notion AI הוא עוזר AI משולב ישירות ב-Notion. הוא יכול לכתוב, לסכם, לתרגם ולענות על שאלות תוך שימוש בתוכן סביבת העבודה שלך כהקשר."},{"q":"כמה עולה Notion AI?","a":"Notion AI הוא תוסף ב-$10 לחבר לחודש (חיוב שנתי) לכל תוכנית Notion. כלול בתוכניות Plus, Business ו-Enterprise החל מ-2026."},{"q":"מה זה Notion Developer Platform 3.5?","a":"Notion Developer Platform 3.5 (מאי 2026) מוסיף Workers runtime לפונקציות serverless, Sync API לנתונים בזמן אמת ו-Webhooks לאוטומציה מבוססת אירועים — והופך את Notion לפלטפורמה תכנותית."},{"q":"האם Notion AI יכול לגשת לאינטרנט?","a":"Notion AI עונה על שאלות מתוכן סביבת העבודה שלך. לנתוני אינטרנט בזמן אמת, הוא משתמש באינטגרציות מחוברות ולא בגלישה ישירה באינטרנט."}]'::jsonb WHERE slug = 'notion-ai' AND lang = 'he';

UPDATE tools SET faq = '[{"q":"Qu''est-ce que Notion AI ?","a":"Notion AI est un assistant IA intégré directement dans Notion. Il peut écrire, résumer, traduire et répondre à des questions en utilisant le contenu de votre espace de travail comme contexte."},{"q":"Combien coûte Notion AI ?","a":"Notion AI est un module complémentaire à $10/membre/mois (facturation annuelle) pour tout plan Notion. Inclus dans les plans Plus, Business et Enterprise depuis 2026."},{"q":"Qu''est-ce que Notion Developer Platform 3.5 ?","a":"Notion Developer Platform 3.5 (mai 2026) ajoute Workers runtime pour les fonctions serverless, Sync API pour les données en temps réel et Webhooks pour l''automatisation événementielle — transformant Notion en plateforme programmable."},{"q":"Notion AI peut-il accéder à internet ?","a":"Notion AI répond aux questions à partir du contenu de votre espace de travail. Pour les données web en temps réel, il utilise des intégrations connectées plutôt que la navigation directe sur internet."}]'::jsonb WHERE slug = 'notion-ai' AND lang = 'fr';

UPDATE tools SET faq = '[{"q":"O que é o Notion AI?","a":"O Notion AI é um assistente de IA integrado diretamente no Notion. Pode escrever, resumir, traduzir e responder perguntas usando o conteúdo do seu espaço de trabalho como contexto."},{"q":"Quanto custa o Notion AI?","a":"O Notion AI é um complemento a $10/membro/mês (cobrança anual) para qualquer plano do Notion. Incluído nos planos Plus, Business e Enterprise desde 2026."},{"q":"O que é o Notion Developer Platform 3.5?","a":"O Notion Developer Platform 3.5 (maio de 2026) adiciona Workers runtime para funções serverless, Sync API para dados em tempo real e Webhooks para automação baseada em eventos — transformando o Notion em uma plataforma programável."},{"q":"O Notion AI pode acessar a internet?","a":"O Notion AI responde perguntas usando o conteúdo do seu espaço de trabalho. Para dados da web em tempo real, usa integrações conectadas em vez de navegar diretamente na internet."}]'::jsonb WHERE slug = 'notion-ai' AND lang = 'pt';

-- ==================== MICROSOFT COPILOT ====================
UPDATE tools SET faq = '[{"q":"Что такое Microsoft Copilot?","a":"Microsoft Copilot — AI-ассистент Microsoft, интегрированный в Windows, Microsoft 365 (Word, Excel, Outlook, Teams), Edge и Bing. Использует GPT-4o для помощи с задачами во всей экосистеме Microsoft."},{"q":"Сколько стоит Microsoft Copilot?","a":"Бесплатно в Windows и Bing. Microsoft 365 Copilot для бизнеса — $30/пользователь/месяц в дополнение к подписке Microsoft 365. Copilot+ PC включает дополнительные AI-функции на устройстве."},{"q":"Что умеет Microsoft Copilot в Excel?","a":"Copilot в Excel создаёт формулы, сводные таблицы, диаграммы, анализирует данные и отвечает на вопросы о таблицах на естественном языке."},{"q":"Microsoft Copilot — это то же самое что GitHub Copilot?","a":"Нет. Microsoft Copilot — универсальный AI-ассистент для Windows и приложений M365. GitHub Copilot — отдельный продукт для дополнения кода и разработки на github.com/features/copilot."}]'::jsonb WHERE slug = 'microsoft-copilot' AND lang = 'ru';
UPDATE tools SET faq = '[{"q":"¿Qué es Microsoft Copilot?","a":"Microsoft Copilot es el asistente de IA de Microsoft integrado en Windows, Microsoft 365 (Word, Excel, Outlook, Teams), Edge y Bing. Usa GPT-4o para asistir con tareas en todo el ecosistema Microsoft."},{"q":"¿Cuánto cuesta Microsoft Copilot?","a":"Gratis en Windows y Bing. Microsoft 365 Copilot para empresas cuesta $30/usuario/mes añadido a una suscripción Microsoft 365. Los PC Copilot+ incluyen funciones de IA adicionales en el dispositivo."},{"q":"¿Qué puede hacer Microsoft Copilot en Excel?","a":"Copilot en Excel puede generar fórmulas, crear tablas dinámicas, resumir datos, crear gráficos y responder preguntas sobre tu hoja de cálculo en lenguaje natural."},{"q":"¿Microsoft Copilot es lo mismo que GitHub Copilot?","a":"No. Microsoft Copilot es un asistente de IA de propósito general para Windows y apps M365. GitHub Copilot es un producto separado enfocado en la compleción de código en github.com/features/copilot."}]'::jsonb WHERE slug = 'microsoft-copilot' AND lang = 'es';
UPDATE tools SET faq = '[{"q":"Was ist Microsoft Copilot?","a":"Microsoft Copilot ist Microsofts KI-Assistent, der in Windows, Microsoft 365 (Word, Excel, Outlook, Teams), Edge und Bing integriert ist. Er verwendet GPT-4o, um bei Aufgaben im gesamten Microsoft-Ökosystem zu helfen."},{"q":"Was kostet Microsoft Copilot?","a":"Kostenlos in Windows und Bing. Microsoft 365 Copilot für Unternehmen kostet $30/Nutzer/Monat zusätzlich zu einem Microsoft 365-Abonnement. Copilot+ PCs enthalten zusätzliche On-Device-KI-Funktionen."},{"q":"Was kann Microsoft Copilot in Excel?","a":"Copilot in Excel kann Formeln erstellen, Pivot-Tabellen anlegen, Daten zusammenfassen, Diagramme erstellen und Fragen zur Tabellenkalkulation in natürlicher Sprache beantworten."},{"q":"Ist Microsoft Copilot dasselbe wie GitHub Copilot?","a":"Nein. Microsoft Copilot ist ein Allzweck-KI-Assistent für Windows und M365-Apps. GitHub Copilot ist ein separates Produkt für Code-Vervollständigung auf github.com/features/copilot."}]'::jsonb WHERE slug = 'microsoft-copilot' AND lang = 'de';
UPDATE tools SET faq = '[{"q":"Що таке Microsoft Copilot?","a":"Microsoft Copilot — AI-асистент Microsoft, інтегрований у Windows, Microsoft 365 (Word, Excel, Outlook, Teams), Edge та Bing. Використовує GPT-4o для допомоги із завданнями в усій екосистемі Microsoft."},{"q":"Скільки коштує Microsoft Copilot?","a":"Безкоштовно у Windows та Bing. Microsoft 365 Copilot для бізнесу — $30/користувач/місяць на додаток до підписки Microsoft 365. Copilot+ PC включає додаткові AI-функції на пристрої."},{"q":"Що вміє Microsoft Copilot в Excel?","a":"Copilot в Excel створює формули, зведені таблиці, діаграми, аналізує дані та відповідає на запитання про таблиці природною мовою."},{"q":"Microsoft Copilot і GitHub Copilot — це одне й те саме?","a":"Ні. Microsoft Copilot — універсальний AI-асистент для Windows і додатків M365. GitHub Copilot — окремий продукт для доповнення коду на github.com/features/copilot."}]'::jsonb WHERE slug = 'microsoft-copilot' AND lang = 'ua';
UPDATE tools SET faq = '[{"q":"מה זה Microsoft Copilot?","a":"Microsoft Copilot הוא עוזר ה-AI של Microsoft המשולב ב-Windows, Microsoft 365 (Word, Excel, Outlook, Teams), Edge ו-Bing. הוא משתמש ב-GPT-4o לסיוע במשימות בכל מערכת האקולוגית של Microsoft."},{"q":"כמה עולה Microsoft Copilot?","a":"חינם ב-Windows וב-Bing. Microsoft 365 Copilot לעסקים עולה $30 למשתמש לחודש בנוסף למנוי Microsoft 365. מחשבי Copilot+ כוללים תכונות AI נוספות במכשיר."},{"q":"מה Microsoft Copilot יכול לעשות ב-Excel?","a":"Copilot ב-Excel יכול ליצור נוסחאות, טבלאות ציר, תרשימים, לסכם נתונים ולענות על שאלות לגבי הגיליון האלקטרוני בשפה טבעית."},{"q":"האם Microsoft Copilot זהה ל-GitHub Copilot?","a":"לא. Microsoft Copilot הוא עוזר AI כללי ל-Windows ואפליקציות M365. GitHub Copilot הוא מוצר נפרד המתמקד בהשלמת קוד ב-github.com/features/copilot."}]'::jsonb WHERE slug = 'microsoft-copilot' AND lang = 'he';
UPDATE tools SET faq = '[{"q":"Qu''est-ce que Microsoft Copilot ?","a":"Microsoft Copilot est l''assistant IA de Microsoft intégré dans Windows, Microsoft 365 (Word, Excel, Outlook, Teams), Edge et Bing. Il utilise GPT-4o pour assister avec les tâches dans tout l''écosystème Microsoft."},{"q":"Combien coûte Microsoft Copilot ?","a":"Gratuit dans Windows et Bing. Microsoft 365 Copilot pour les entreprises coûte $30/utilisateur/mois en supplément d''un abonnement Microsoft 365. Les PC Copilot+ incluent des fonctionnalités IA supplémentaires sur l''appareil."},{"q":"Que peut faire Microsoft Copilot dans Excel ?","a":"Copilot dans Excel peut générer des formules, créer des tableaux croisés dynamiques, résumer des données, créer des graphiques et répondre à des questions sur votre feuille de calcul en langage naturel."},{"q":"Microsoft Copilot est-il la même chose que GitHub Copilot ?","a":"Non. Microsoft Copilot est un assistant IA polyvalent pour Windows et les applications M365. GitHub Copilot est un produit séparé axé sur la complétion de code sur github.com/features/copilot."}]'::jsonb WHERE slug = 'microsoft-copilot' AND lang = 'fr';
UPDATE tools SET faq = '[{"q":"O que é o Microsoft Copilot?","a":"O Microsoft Copilot é o assistente de IA da Microsoft integrado ao Windows, Microsoft 365 (Word, Excel, Outlook, Teams), Edge e Bing. Usa GPT-4o para auxiliar com tarefas em todo o ecossistema Microsoft."},{"q":"Quanto custa o Microsoft Copilot?","a":"Grátis no Windows e Bing. O Microsoft 365 Copilot para empresas custa $30/usuário/mês além da assinatura Microsoft 365. PCs Copilot+ incluem recursos de IA adicionais no dispositivo."},{"q":"O que o Microsoft Copilot pode fazer no Excel?","a":"O Copilot no Excel pode gerar fórmulas, criar tabelas dinâmicas, resumir dados, criar gráficos e responder perguntas sobre sua planilha em linguagem natural."},{"q":"O Microsoft Copilot é o mesmo que o GitHub Copilot?","a":"Não. O Microsoft Copilot é um assistente de IA de uso geral para Windows e apps M365. O GitHub Copilot é um produto separado focado em conclusão de código em github.com/features/copilot."}]'::jsonb WHERE slug = 'microsoft-copilot' AND lang = 'pt';

-- ==================== CLAUDE CODE ====================
UPDATE tools SET faq = '[{"q":"Что такое Claude Code?","a":"Claude Code — официальный CLI-инструмент Anthropic для разработки. Работает в терминале, читает кодовую базу, пишет код, выполняет команды, исправляет баги и завершает многофайловые задачи как автономный агент."},{"q":"Сколько стоит Claude Code?","a":"Включён в Claude Pro ($20/месяц), Max ($100/месяц), Team и Enterprise. Использование тарифицируется по API-токенам, потреблённым во время агентных задач."},{"q":"Чем Claude Code отличается от Cursor?","a":"Claude Code работает в терминале — без GUI. Для разработчиков, предпочитающих CLI. Cursor — полноценная IDE с визуальным интерфейсом на базе VS Code."},{"q":"Что Claude Code умеет делать автономно?","a":"Читать и редактировать файлы, выполнять команды оболочки, запускать тесты, искать по кодовой базе, управлять git и завершать многошаговые инженерные задачи с минимальными подсказками."}]'::jsonb WHERE slug = 'claude-code' AND lang = 'ru';
UPDATE tools SET faq = '[{"q":"¿Qué es Claude Code?","a":"Claude Code es la herramienta CLI oficial de Anthropic para ingeniería de software. Funciona en la terminal, lee tu base de código, escribe código, ejecuta comandos, corrige errores y completa tareas de múltiples archivos como agente autónomo."},{"q":"¿Cuánto cuesta Claude Code?","a":"Incluido en Claude Pro ($20/mes), Max ($100/mes), Team y Enterprise. El uso se mide por tokens de API consumidos durante las tareas agénticas."},{"q":"¿En qué se diferencia Claude Code de Cursor?","a":"Claude Code funciona en la terminal — sin GUI. Está diseñado para desarrolladores que prefieren flujos de trabajo CLI. Cursor es un IDE completo con interfaz visual basado en VS Code."},{"q":"¿Qué puede hacer Claude Code de forma autónoma?","a":"Leer y editar archivos, ejecutar comandos de shell, ejecutar pruebas, buscar en la base de código, gestionar git y completar tareas de ingeniería de múltiples pasos con mínimos prompts."}]'::jsonb WHERE slug = 'claude-code' AND lang = 'es';
UPDATE tools SET faq = '[{"q":"Was ist Claude Code?","a":"Claude Code ist Anthropics offizielles CLI-Tool für Software-Engineering. Es läuft im Terminal, liest die Codebasis, schreibt Code, führt Befehle aus, behebt Bugs und schließt Multi-Datei-Aufgaben als autonomer Agent ab."},{"q":"Was kostet Claude Code?","a":"Enthalten in Claude Pro ($20/Monat), Max ($100/Monat), Team und Enterprise. Die Nutzung wird nach API-Tokens gemessen, die während agentischer Aufgaben verbraucht werden."},{"q":"Wie unterscheidet sich Claude Code von Cursor?","a":"Claude Code läuft im Terminal — ohne GUI. Es ist für Entwickler gedacht, die CLI-Workflows bevorzugen. Cursor ist eine vollständige IDE mit visueller Oberfläche auf VS Code-Basis."},{"q":"Was kann Claude Code autonom tun?","a":"Dateien lesen und bearbeiten, Shell-Befehle ausführen, Tests ausführen, die Codebasis durchsuchen, git verwalten und mehrstufige Engineering-Aufgaben mit minimalem Prompting abschließen."}]'::jsonb WHERE slug = 'claude-code' AND lang = 'de';
UPDATE tools SET faq = '[{"q":"Що таке Claude Code?","a":"Claude Code — офіційний CLI-інструмент Anthropic для розробки програмного забезпечення. Працює в терміналі, читає кодову базу, пише код, виконує команди, виправляє баги та завершує багатофайлові завдання як автономний агент."},{"q":"Скільки коштує Claude Code?","a":"Включений у Claude Pro ($20/місяць), Max ($100/місяць), Team та Enterprise. Використання тарифікується за API-токенами, спожитими під час агентних завдань."},{"q":"Чим Claude Code відрізняється від Cursor?","a":"Claude Code працює в терміналі — без GUI. Для розробників, які надають перевагу CLI. Cursor — повноцінна IDE з візуальним інтерфейсом на базі VS Code."},{"q":"Що Claude Code вміє робити автономно?","a":"Читати та редагувати файли, виконувати команди оболонки, запускати тести, шукати по кодовій базі, керувати git та завершувати багатокрокові інженерні завдання з мінімальними підказками."}]'::jsonb WHERE slug = 'claude-code' AND lang = 'ua';
UPDATE tools SET faq = '[{"q":"מה זה Claude Code?","a":"Claude Code הוא כלי CLI רשמי של Anthropic לפיתוח תוכנה. הוא פועל בטרמינל, קורא את קוד הפרויקט, כותב קוד, מריץ פקודות, מתקן באגים ומשלים משימות מרובות קבצים כסוכן אוטונומי."},{"q":"כמה עולה Claude Code?","a":"כלול ב-Claude Pro (‏$20 לחודש), Max (‏$100 לחודש), Team ו-Enterprise. השימוש נמדד לפי טוקני API שנצרכים במהלך משימות אגנטיות."},{"q":"במה Claude Code שונה מ-Cursor?","a":"Claude Code פועל בטרמינל — ללא ממשק גרפי. הוא מיועד למפתחים המעדיפים זרימות עבודה של CLI. Cursor הוא IDE מלא עם ממשק ויזואלי מבוסס VS Code."},{"q":"מה Claude Code יכול לעשות באופן אוטונומי?","a":"לקרוא ולערוך קבצים, להריץ פקודות shell, להריץ בדיקות, לחפש בקוד הפרויקט, לנהל git ולהשלים משימות הנדסה מרובות שלבים עם הנחיות מינימליות."}]'::jsonb WHERE slug = 'claude-code' AND lang = 'he';
UPDATE tools SET faq = '[{"q":"Qu''est-ce que Claude Code ?","a":"Claude Code est l''outil CLI officiel d''Anthropic pour le développement logiciel. Il fonctionne dans le terminal, lit votre base de code, écrit du code, exécute des commandes, corrige des bugs et complète des tâches multi-fichiers comme agent autonome."},{"q":"Combien coûte Claude Code ?","a":"Inclus dans Claude Pro ($20/mois), Max ($100/mois), Team et Enterprise. L''utilisation est mesurée par les tokens API consommés lors des tâches agentiques."},{"q":"En quoi Claude Code diffère-t-il de Cursor ?","a":"Claude Code fonctionne dans le terminal — sans interface graphique. Il est conçu pour les développeurs qui préfèrent les workflows CLI. Cursor est un IDE complet avec interface visuelle basé sur VS Code."},{"q":"Que peut faire Claude Code de manière autonome ?","a":"Lire et modifier des fichiers, exécuter des commandes shell, lancer des tests, rechercher dans la base de code, gérer git et accomplir des tâches d''ingénierie en plusieurs étapes avec un minimum de prompts."}]'::jsonb WHERE slug = 'claude-code' AND lang = 'fr';
UPDATE tools SET faq = '[{"q":"O que é o Claude Code?","a":"O Claude Code é a ferramenta CLI oficial da Anthropic para engenharia de software. Funciona no terminal, lê sua base de código, escreve código, executa comandos, corrige bugs e completa tarefas de múltiplos arquivos como agente autônomo."},{"q":"Quanto custa o Claude Code?","a":"Incluído no Claude Pro ($20/mês), Max ($100/mês), Team e Enterprise. O uso é medido pelos tokens de API consumidos durante tarefas agênticas."},{"q":"Como o Claude Code se diferencia do Cursor?","a":"O Claude Code funciona no terminal — sem interface gráfica. É projetado para desenvolvedores que preferem workflows CLI. O Cursor é um IDE completo com interface visual baseado no VS Code."},{"q":"O que o Claude Code pode fazer de forma autônoma?","a":"Ler e editar arquivos, executar comandos shell, rodar testes, pesquisar na base de código, gerenciar git e completar tarefas de engenharia em múltiplas etapas com prompts mínimos."}]'::jsonb WHERE slug = 'claude-code' AND lang = 'pt';

-- ==================== CLAUDE DESIGN ====================
UPDATE tools SET faq = '[{"q":"Что такое Claude Design?","a":"Claude Design — AI-инструмент дизайна Anthropic, встроенный в Claude. Генерирует UI-макеты, презентации, лендинги и визуальные прототипы через диалог — без дизайнерского ПО."},{"q":"Сколько стоит Claude Design?","a":"Включён в Claude Pro ($20/месяц), Max ($100/месяц), Team и Enterprise без доплаты. Доступен как ранний доступ через Anthropic Labs."},{"q":"Можно ли экспортировать в Figma или в код?","a":"Claude Design генерирует HTML/CSS код дизайнов. Прямой экспорт в Figma недоступен по состоянию на май 2026, но сгенерированный код можно использовать в любом рабочем процессе."},{"q":"Какие дизайны умеет создавать Claude Design?","a":"UI-макеты, лендинги, слайды презентаций, дашборды с данными и маркетинговые материалы. Может извлекать брендовый стиль из существующих материалов и применять его последовательно."}]'::jsonb WHERE slug = 'claude-design' AND lang = 'ru';
UPDATE tools SET faq = '[{"q":"¿Qué es Claude Design?","a":"Claude Design es la herramienta de diseño IA de Anthropic integrada en Claude. Genera maquetas de UI, presentaciones, páginas de destino y prototipos visuales a través de conversación, sin necesidad de software de diseño."},{"q":"¿Cuánto cuesta Claude Design?","a":"Incluido en Claude Pro ($20/mes), Max ($100/mes), Team y Enterprise sin costo adicional. Disponible como acceso anticipado a través de Anthropic Labs."},{"q":"¿Se puede exportar a Figma o a código?","a":"Claude Design puede generar código HTML/CSS para los diseños. La exportación directa a Figma no está disponible a mayo de 2026, pero el código generado puede importarse en cualquier flujo de trabajo."},{"q":"¿Qué tipos de diseños puede crear Claude Design?","a":"Maquetas de UI, páginas de destino, diapositivas de presentación, paneles de datos y materiales de marketing. Puede extraer estilos de marca de materiales existentes y aplicarlos de manera consistente."}]'::jsonb WHERE slug = 'claude-design' AND lang = 'es';
UPDATE tools SET faq = '[{"q":"Was ist Claude Design?","a":"Claude Design ist Anthropics KI-Design-Tool, das in Claude integriert ist. Es generiert UI-Mockups, Präsentationen, Landing Pages und visuelle Prototypen durch Konversation — ohne Design-Software."},{"q":"Was kostet Claude Design?","a":"Enthalten in Claude Pro ($20/Monat), Max ($100/Monat), Team und Enterprise ohne Aufpreis. Verfügbar als Early Access über Anthropic Labs."},{"q":"Kann man nach Figma oder in Code exportieren?","a":"Claude Design kann HTML/CSS-Code für Designs generieren. Direkter Figma-Export ist ab Mai 2026 nicht verfügbar, aber der generierte Code kann in jeden Workflow importiert werden."},{"q":"Welche Designs kann Claude Design erstellen?","a":"UI-Mockups, Landing Pages, Präsentationsfolien, Daten-Dashboards und Marketingmaterialien. Es kann Markenstile aus bestehenden Materialien extrahieren und konsistent anwenden."}]'::jsonb WHERE slug = 'claude-design' AND lang = 'de';
UPDATE tools SET faq = '[{"q":"Що таке Claude Design?","a":"Claude Design — AI-інструмент дизайну Anthropic, вбудований у Claude. Генерує UI-макети, презентації, лендінги та візуальні прототипи через діалог — без дизайнерського ПЗ."},{"q":"Скільки коштує Claude Design?","a":"Включений у Claude Pro ($20/місяць), Max ($100/місяць), Team та Enterprise без доплати. Доступний як ранній доступ через Anthropic Labs."},{"q":"Чи можна експортувати у Figma або в код?","a":"Claude Design генерує HTML/CSS код дизайнів. Прямий експорт у Figma недоступний станом на травень 2026, але згенерований код можна використовувати в будь-якому робочому процесі."},{"q":"Які дизайни вміє створювати Claude Design?","a":"UI-макети, лендінги, слайди презентацій, дашборди з даними та маркетингові матеріали. Може витягувати брендовий стиль з існуючих матеріалів і застосовувати його послідовно."}]'::jsonb WHERE slug = 'claude-design' AND lang = 'ua';
UPDATE tools SET faq = '[{"q":"מה זה Claude Design?","a":"Claude Design הוא כלי עיצוב AI של Anthropic המשולב ב-Claude. הוא מייצר מוקאפים של ממשק משתמש, מצגות, דפי נחיתה ואבות טיפוס ויזואליים דרך שיחה — ללא תוכנת עיצוב."},{"q":"כמה עולה Claude Design?","a":"כלול ב-Claude Pro (‏$20 לחודש), Max (‏$100 לחודש), Team ו-Enterprise ללא עלות נוספת. זמין כגישה מוקדמת דרך Anthropic Labs."},{"q":"האם ניתן לייצא ל-Figma או לקוד?","a":"Claude Design יכול לייצר קוד HTML/CSS לעיצובים. ייצוא ישיר ל-Figma אינו זמין נכון למאי 2026, אך הקוד שנוצר יכול לשמש בכל זרימת עבודה."},{"q":"אילו סוגי עיצובים יכול Claude Design ליצור?","a":"מוקאפים של ממשק משתמש, דפי נחיתה, שקופיות מצגת, לוחות מחוונים ומסמכי שיווק. הוא יכול לחלץ סגנון מותג מחומרים קיימים ולהחיל אותו באופן עקבי."}]'::jsonb WHERE slug = 'claude-design' AND lang = 'he';
UPDATE tools SET faq = '[{"q":"Qu''est-ce que Claude Design ?","a":"Claude Design est l''outil de design IA d''Anthropic intégré dans Claude. Il génère des maquettes UI, présentations, pages d''atterrissage et prototypes visuels par conversation — sans logiciel de design."},{"q":"Combien coûte Claude Design ?","a":"Inclus dans Claude Pro ($20/mois), Max ($100/mois), Team et Enterprise sans frais supplémentaires. Disponible en accès anticipé via Anthropic Labs."},{"q":"Peut-on exporter vers Figma ou en code ?","a":"Claude Design peut générer du code HTML/CSS pour les designs. L''export direct vers Figma n''est pas disponible en mai 2026, mais le code généré peut être utilisé dans n''importe quel workflow."},{"q":"Quels types de designs Claude Design peut-il créer ?","a":"Maquettes UI, pages d''atterrissage, diapositives de présentation, tableaux de bord de données et supports marketing. Il peut extraire le style de marque de matériaux existants et l''appliquer de manière cohérente."}]'::jsonb WHERE slug = 'claude-design' AND lang = 'fr';
UPDATE tools SET faq = '[{"q":"O que é o Claude Design?","a":"O Claude Design é a ferramenta de design com IA da Anthropic integrada ao Claude. Gera mockups de UI, apresentações, landing pages e protótipos visuais por meio de conversa — sem software de design."},{"q":"Quanto custa o Claude Design?","a":"Incluído no Claude Pro ($20/mês), Max ($100/mês), Team e Enterprise sem custo adicional. Disponível como acesso antecipado via Anthropic Labs."},{"q":"É possível exportar para Figma ou em código?","a":"O Claude Design pode gerar código HTML/CSS para os designs. Exportação direta para Figma não está disponível em maio de 2026, mas o código gerado pode ser usado em qualquer fluxo de trabalho."},{"q":"Que tipos de designs o Claude Design pode criar?","a":"Mockups de UI, landing pages, slides de apresentação, painéis de dados e materiais de marketing. Pode extrair o estilo de marca de materiais existentes e aplicá-lo de forma consistente."}]'::jsonb WHERE slug = 'claude-design' AND lang = 'pt';

-- ==================== V0 BY VERCEL ====================
UPDATE tools SET faq = '[{"q":"Что такое V0 by Vercel?","a":"V0 — AI-генератор UI от Vercel. Опишите интерфейс текстом — получите готовый React и Tailwind CSS код, который деплоится прямо на Vercel."},{"q":"Сколько стоит V0?","a":"Бесплатный тариф с ограниченными кредитами. Premium — $20/месяц. Командные планы для совместных проектов."},{"q":"Умеет ли V0 создавать полноценные приложения?","a":"V0 фокусируется на генерации фронтенда. Для полноценных приложений интегрируется с платформой Vercel, поддерживает API-роуты и подключение баз данных."},{"q":"Какие фреймворки поддерживает V0?","a":"V0 генерирует React с Tailwind CSS и компонентами shadcn/ui. Совместим с Next.js и нативно деплоится на Vercel."}]'::jsonb WHERE slug = 'v0-by-vercel' AND lang = 'ru';
UPDATE tools SET faq = '[{"q":"¿Qué es V0 by Vercel?","a":"V0 es el generador de UI con IA de Vercel. Describe una interfaz en lenguaje natural y V0 genera código React y Tailwind CSS listo para producción que se despliega directamente en Vercel."},{"q":"¿Cuánto cuesta V0?","a":"Nivel gratuito con créditos limitados. Premium es $20/mes. Planes de equipo disponibles para proyectos colaborativos."},{"q":"¿Puede V0 generar aplicaciones completas?","a":"V0 se centra en la generación de UI frontend. Para apps completas, se integra con la plataforma de Vercel y puede generar rutas API y conexiones de base de datos."},{"q":"¿Qué frameworks soporta V0?","a":"V0 genera principalmente React con Tailwind CSS y componentes shadcn/ui. Compatible con Next.js y despliega de forma nativa en Vercel."}]'::jsonb WHERE slug = 'v0-by-vercel' AND lang = 'es';
UPDATE tools SET faq = '[{"q":"Was ist V0 by Vercel?","a":"V0 ist Vercels KI-betriebener UI-Generator. Beschreibe eine Benutzeroberfläche in natürlicher Sprache und V0 generiert produktionsfertigen React- und Tailwind-CSS-Code, der direkt auf Vercel deployed wird."},{"q":"Was kostet V0?","a":"Kostenloses Kontingent mit begrenzten Credits. Premium kostet $20/Monat. Team-Pläne für kollaborative Projekte verfügbar."},{"q":"Kann V0 vollständige Apps generieren?","a":"V0 fokussiert sich auf Frontend-UI-Generierung. Für vollständige Apps integriert es sich mit der Vercel-Plattform und kann API-Routen und Datenbankverbindungen erstellen."},{"q":"Welche Frameworks unterstützt V0?","a":"V0 generiert hauptsächlich React mit Tailwind CSS und shadcn/ui-Komponenten. Kompatibel mit Next.js und deployed nativ auf Vercel."}]'::jsonb WHERE slug = 'v0-by-vercel' AND lang = 'de';
UPDATE tools SET faq = '[{"q":"Що таке V0 by Vercel?","a":"V0 — AI-генератор UI від Vercel. Опишіть інтерфейс текстом — отримаєте готовий React і Tailwind CSS код, який деплоїться прямо на Vercel."},{"q":"Скільки коштує V0?","a":"Безкоштовний тариф з обмеженими кредитами. Premium — $20/місяць. Командні плани для спільних проектів."},{"q":"Чи вміє V0 створювати повноцінні застосунки?","a":"V0 фокусується на генерації фронтенду. Для повноцінних застосунків інтегрується з платформою Vercel, підтримує API-роути та підключення баз даних."},{"q":"Які фреймворки підтримує V0?","a":"V0 генерує React з Tailwind CSS та компонентами shadcn/ui. Сумісний з Next.js та нативно деплоїться на Vercel."}]'::jsonb WHERE slug = 'v0-by-vercel' AND lang = 'ua';
UPDATE tools SET faq = '[{"q":"מה זה V0 by Vercel?","a":"V0 הוא מחולל UI מבוסס AI של Vercel. תאר ממשק בשפה טבעית ו-V0 מייצר קוד React ו-Tailwind CSS מוכן לייצור שנפרס ישירות ב-Vercel."},{"q":"כמה עולה V0?","a":"רמה חינמית עם קרדיטים מוגבלים. Premium עולה $20 לחודש. תוכניות צוות זמינות לפרויקטים שיתופיים."},{"q":"האם V0 יכול לייצר אפליקציות מלאות?","a":"V0 מתמקד ביצירת ממשק משתמש frontend. לאפליקציות מלאות, הוא משתלב עם פלטפורמת Vercel ויכול ליצור נתיבי API וחיבורי בסיס נתונים."},{"q":"אילו פריימוורקים תומך V0?","a":"V0 מייצר בעיקר React עם Tailwind CSS ורכיבי shadcn/ui. תואם ל-Next.js ונפרס באופן מקורי ב-Vercel."}]'::jsonb WHERE slug = 'v0-by-vercel' AND lang = 'he';
UPDATE tools SET faq = '[{"q":"Qu''est-ce que V0 by Vercel ?","a":"V0 est le générateur d''UI propulsé par IA de Vercel. Décrivez une interface en langage naturel et V0 génère du code React et Tailwind CSS prêt pour la production, qui se déploie directement sur Vercel."},{"q":"Combien coûte V0 ?","a":"Niveau gratuit avec crédits limités. Premium à $20/mois. Plans équipe disponibles pour les projets collaboratifs."},{"q":"V0 peut-il générer des applications complètes ?","a":"V0 se concentre sur la génération d''UI frontend. Pour des apps complètes, il s''intègre avec la plateforme Vercel et peut créer des routes API et des connexions de base de données."},{"q":"Quels frameworks V0 prend-il en charge ?","a":"V0 génère principalement React avec Tailwind CSS et les composants shadcn/ui. Compatible avec Next.js et se déploie nativement sur Vercel."}]'::jsonb WHERE slug = 'v0-by-vercel' AND lang = 'fr';
UPDATE tools SET faq = '[{"q":"O que é o V0 by Vercel?","a":"O V0 é o gerador de UI com IA da Vercel. Descreva uma interface em linguagem natural e o V0 gera código React e Tailwind CSS pronto para produção, que é implantado diretamente na Vercel."},{"q":"Quanto custa o V0?","a":"Nível gratuito com créditos limitados. Premium custa $20/mês. Planos de equipe disponíveis para projetos colaborativos."},{"q":"O V0 pode gerar aplicativos completos?","a":"O V0 foca na geração de UI frontend. Para apps completos, integra-se com a plataforma Vercel e pode criar rotas de API e conexões de banco de dados."},{"q":"Quais frameworks o V0 suporta?","a":"O V0 gera principalmente React com Tailwind CSS e componentes shadcn/ui. Compatível com Next.js e implanta nativamente na Vercel."}]'::jsonb WHERE slug = 'v0-by-vercel' AND lang = 'pt';

-- ==================== CHATGPT IMAGES ====================
UPDATE tools SET faq = '[{"q":"Что такое ChatGPT Images?","a":"ChatGPT Images (на базе gpt-image-2) — функция генерации изображений внутри ChatGPT. Создаёт и редактирует изображения по текстовым запросам с точным рендерингом текста и многоязычными подписями."},{"q":"Сколько стоит ChatGPT Images?","a":"Доступно на планах ChatGPT Plus ($20/месяц), Pro ($200/месяц) и Team. Пользователям бесплатного плана доступен ограниченный доступ. API тарифицируется по токенам через gpt-image-2."},{"q":"Что произошло с DALL-E 3?","a":"DALL-E 2 и DALL-E 3 выведены из эксплуатации в мае 2026 и заменены gpt-image-2, который поддерживает разрешение до 2K, многоязычный рендеринг текста и улучшенное следование инструкциям."},{"q":"Может ли ChatGPT Images редактировать существующие фото?","a":"Да. ChatGPT Images поддерживает редактирование изображений — загрузите фото и попросите ChatGPT изменить отдельные элементы, фон, добавить объекты или применить стиль."}]'::jsonb WHERE slug = 'chatgpt-images' AND lang = 'ru';
UPDATE tools SET faq = '[{"q":"¿Qué es ChatGPT Images?","a":"ChatGPT Images (impulsado por gpt-image-2) es la función de generación de imágenes dentro de ChatGPT. Genera y edita imágenes a partir de prompts de texto con renderizado preciso de texto y subtítulos multilingües."},{"q":"¿Cuánto cuesta ChatGPT Images?","a":"Disponible en planes ChatGPT Plus ($20/mes), Pro ($200/mes) y Team. Los usuarios del plan gratuito tienen acceso limitado. El uso de API se factura por tokens a través de gpt-image-2."},{"q":"¿Qué pasó con DALL-E 3?","a":"DALL-E 2 y DALL-E 3 fueron retirados en mayo de 2026 y reemplazados por gpt-image-2, que admite resolución de hasta 2K, renderizado de texto multilingüe y seguimiento mejorado de instrucciones."},{"q":"¿Puede ChatGPT Images editar fotos existentes?","a":"Sí. ChatGPT Images admite edición de imágenes: sube una imagen y pide a ChatGPT que modifique elementos específicos, cambie fondos, añada objetos o aplique cambios de estilo."}]'::jsonb WHERE slug = 'chatgpt-images' AND lang = 'es';
UPDATE tools SET faq = '[{"q":"Was ist ChatGPT Images?","a":"ChatGPT Images (betrieben von gpt-image-2) ist die Bildgenerierungsfunktion in ChatGPT. Es generiert und bearbeitet Bilder aus Textprompts mit präzisem Text-Rendering und mehrsprachigen Bildunterschriften."},{"q":"Was kostet ChatGPT Images?","a":"Verfügbar in ChatGPT Plus ($20/Monat), Pro ($200/Monat) und Team-Plänen. Kostenlose Nutzer haben begrenzten Zugang. API-Nutzung wird per Token über gpt-image-2 abgerechnet."},{"q":"Was ist mit DALL-E 3 passiert?","a":"DALL-E 2 und DALL-E 3 wurden im Mai 2026 eingestellt und durch gpt-image-2 ersetzt, das Auflösungen bis 2K, mehrsprachiges Text-Rendering und verbesserte Anweisungsfolge unterstützt."},{"q":"Kann ChatGPT Images bestehende Fotos bearbeiten?","a":"Ja. ChatGPT Images unterstützt Bildbearbeitung — lade ein Bild hoch und bitte ChatGPT, bestimmte Elemente zu ändern, Hintergründe zu wechseln, Objekte hinzuzufügen oder Stiländerungen vorzunehmen."}]'::jsonb WHERE slug = 'chatgpt-images' AND lang = 'de';
UPDATE tools SET faq = '[{"q":"Що таке ChatGPT Images?","a":"ChatGPT Images (на базі gpt-image-2) — функція генерації зображень всередині ChatGPT. Створює та редагує зображення за текстовими запитами з точним рендерингом тексту та багатомовними підписами."},{"q":"Скільки коштує ChatGPT Images?","a":"Доступно на планах ChatGPT Plus ($20/місяць), Pro ($200/місяць) та Team. Користувачам безкоштовного плану доступний обмежений доступ. API тарифікується за токенами через gpt-image-2."},{"q":"Що сталося з DALL-E 3?","a":"DALL-E 2 та DALL-E 3 виведені з експлуатації у травні 2026 і замінені gpt-image-2, який підтримує роздільну здатність до 2K, багатомовний рендеринг тексту та покращене дотримання інструкцій."},{"q":"Чи може ChatGPT Images редагувати існуючі фото?","a":"Так. ChatGPT Images підтримує редагування зображень — завантажте фото і попросіть ChatGPT змінити окремі елементи, фон, додати об''єкти або застосувати стиль."}]'::jsonb WHERE slug = 'chatgpt-images' AND lang = 'ua';
UPDATE tools SET faq = '[{"q":"מה זה ChatGPT Images?","a":"ChatGPT Images (מופעל על ידי gpt-image-2) הוא תכונת יצירת התמונות בתוך ChatGPT. הוא מייצר ועורך תמונות מפרומפטים טקסטואליים עם רינדור טקסט מדויק וכיתובים רב-לשוניים."},{"q":"כמה עולה ChatGPT Images?","a":"זמין בתוכניות ChatGPT Plus (‏$20 לחודש), Pro (‏$200 לחודש) ו-Team. למשתמשי התוכנית החינמית יש גישה מוגבלת. שימוש ב-API מחויב לפי טוקנים דרך gpt-image-2."},{"q":"מה קרה ל-DALL-E 3?","a":"DALL-E 2 ו-DALL-E 3 הופסקו במאי 2026 והוחלפו ב-gpt-image-2, התומך ברזולוציה של עד 2K, רינדור טקסט רב-לשוני ועמידה משופרת בהוראות."},{"q":"האם ChatGPT Images יכול לערוך תמונות קיימות?","a":"כן. ChatGPT Images תומך בעריכת תמונות — העלה תמונה ובקש מ-ChatGPT לשנות אלמנטים ספציפיים, לשנות רקעים, להוסיף אובייקטים או להחיל שינויי סגנון."}]'::jsonb WHERE slug = 'chatgpt-images' AND lang = 'he';
UPDATE tools SET faq = '[{"q":"Qu''est-ce que ChatGPT Images ?","a":"ChatGPT Images (propulsé par gpt-image-2) est la fonction de génération d''images dans ChatGPT. Il génère et modifie des images à partir de prompts textuels avec un rendu de texte précis et des légendes multilingues."},{"q":"Combien coûte ChatGPT Images ?","a":"Disponible dans les plans ChatGPT Plus ($20/mois), Pro ($200/mois) et Team. Les utilisateurs du plan gratuit ont un accès limité. L''utilisation API est facturée par token via gpt-image-2."},{"q":"Que s''est-il passé avec DALL-E 3 ?","a":"DALL-E 2 et DALL-E 3 ont été retirés en mai 2026 et remplacés par gpt-image-2, qui supporte une résolution jusqu''à 2K, le rendu de texte multilingue et un meilleur suivi des instructions."},{"q":"ChatGPT Images peut-il modifier des photos existantes ?","a":"Oui. ChatGPT Images prend en charge l''édition d''images : téléchargez une image et demandez à ChatGPT de modifier des éléments spécifiques, changer les arrière-plans, ajouter des objets ou appliquer des changements de style."}]'::jsonb WHERE slug = 'chatgpt-images' AND lang = 'fr';
UPDATE tools SET faq = '[{"q":"O que é o ChatGPT Images?","a":"O ChatGPT Images (alimentado pelo gpt-image-2) é o recurso de geração de imagens dentro do ChatGPT. Gera e edita imagens a partir de prompts de texto com renderização precisa de texto e legendas multilíngues."},{"q":"Quanto custa o ChatGPT Images?","a":"Disponível nos planos ChatGPT Plus ($20/mês), Pro ($200/mês) e Team. Usuários do plano gratuito têm acesso limitado. O uso da API é cobrado por token via gpt-image-2."},{"q":"O que aconteceu com o DALL-E 3?","a":"O DALL-E 2 e o DALL-E 3 foram descontinuados em maio de 2026 e substituídos pelo gpt-image-2, que suporta resolução de até 2K, renderização de texto multilíngue e melhor seguimento de instruções."},{"q":"O ChatGPT Images pode editar fotos existentes?","a":"Sim. O ChatGPT Images suporta edição de imagens — carregue uma imagem e peça ao ChatGPT para modificar elementos específicos, trocar fundos, adicionar objetos ou aplicar mudanças de estilo."}]'::jsonb WHERE slug = 'chatgpt-images' AND lang = 'pt';

-- ==================== ZAPIER AI ====================
UPDATE tools SET faq = '[{"q":"Что такое Zapier AI?","a":"Zapier AI — AI-слой внутри Zapier для создания автоматизированных воркфлоу на естественном языке. Опишите что хотите автоматизировать — Zapier AI создаст воркфлоу, соединяющий 7000+ приложений."},{"q":"Сколько стоит Zapier?","a":"Бесплатный план — 100 задач/месяц, 5 Zap. Starter — $29.99/месяц (750 задач). Professional — $73.50/месяц (2K задач). Team — $103.50/месяц. Компании — по запросу."},{"q":"Что умеет автоматизировать Zapier AI?","a":"Ответы на письма, обновления CRM, публикации в соцсетях, ввод данных, маршрутизацию лидов и любые повторяющиеся задачи в 7000+ подключённых приложениях — по триггеру или по расписанию."},{"q":"Чем Zapier AI отличается от n8n?","a":"Zapier — no-code SaaS с крупнейшей библиотекой интеграций. n8n — open-source с возможностью самостоятельного хостинга, предлагает больше гибкости и ниже стоимость при масштабировании для технических пользователей."}]'::jsonb WHERE slug = 'zapier-ai' AND lang = 'ru';
UPDATE tools SET faq = '[{"q":"¿Qué es Zapier AI?","a":"Zapier AI es la capa de IA dentro de Zapier que permite crear flujos de trabajo automatizados usando lenguaje natural. Describe lo que quieres automatizar y Zapier AI genera el flujo conectando más de 7.000 apps."},{"q":"¿Cuánto cuesta Zapier?","a":"Plan gratuito con 100 tareas/mes y 5 Zaps. Starter es $29.99/mes (750 tareas). Professional es $73.50/mes (2K tareas). Team es $103.50/mes. Enterprise a precio personalizado."},{"q":"¿Qué puede automatizar Zapier AI?","a":"Respuestas de correo, actualizaciones de CRM, publicaciones en redes sociales, entrada de datos, enrutamiento de leads y cualquier tarea repetitiva en más de 7.000 apps conectadas, por evento o por horario."},{"q":"¿En qué se diferencia Zapier AI de n8n?","a":"Zapier es un SaaS sin código con la mayor biblioteca de integraciones. n8n es de código abierto y autoalojable, ofreciendo más flexibilidad y menor costo a escala para usuarios técnicos."}]'::jsonb WHERE slug = 'zapier-ai' AND lang = 'es';
UPDATE tools SET faq = '[{"q":"Was ist Zapier AI?","a":"Zapier AI ist die KI-Schicht in Zapier, die es ermöglicht, automatisierte Workflows in natürlicher Sprache zu erstellen. Beschreibe was du automatisieren möchtest, und Zapier AI erstellt den Workflow, der 7.000+ Apps verbindet."},{"q":"Was kostet Zapier?","a":"Kostenloser Plan mit 100 Aufgaben/Monat und 5 Zaps. Starter kostet $29.99/Monat (750 Aufgaben). Professional $73.50/Monat (2K Aufgaben). Team $103.50/Monat. Enterprise auf Anfrage."},{"q":"Was kann Zapier AI automatisieren?","a":"E-Mail-Antworten, CRM-Updates, Social-Media-Posts, Dateneingabe, Lead-Routing und alle wiederkehrenden Aufgaben in 7.000+ verbundenen Apps — ausgelöst durch Ereignisse oder Zeitpläne."},{"q":"Wie unterscheidet sich Zapier AI von n8n?","a":"Zapier ist eine No-Code-SaaS-Lösung mit der größten Integrationsbibliothek. n8n ist Open-Source und selbst-hostbar und bietet mehr Flexibilität und niedrigere Kosten bei größerem Umfang für technische Nutzer."}]'::jsonb WHERE slug = 'zapier-ai' AND lang = 'de';
UPDATE tools SET faq = '[{"q":"Що таке Zapier AI?","a":"Zapier AI — AI-шар всередині Zapier для створення автоматизованих воркфлоу природною мовою. Опишіть що хочете автоматизувати — Zapier AI створить воркфлоу, що з''єднує 7000+ додатків."},{"q":"Скільки коштує Zapier?","a":"Безкоштовний план — 100 завдань/місяць, 5 Zap. Starter — $29.99/місяць (750 завдань). Professional — $73.50/місяць (2K завдань). Team — $103.50/місяць. Компанії — за запитом."},{"q":"Що вміє автоматизувати Zapier AI?","a":"Відповіді на листи, оновлення CRM, публікації в соцмережах, введення даних, маршрутизацію лідів та будь-які повторювані завдання в 7000+ підключених додатках — за тригером або розкладом."},{"q":"Чим Zapier AI відрізняється від n8n?","a":"Zapier — no-code SaaS з найбільшою бібліотекою інтеграцій. n8n — open-source з можливістю самостійного хостингу, пропонує більше гнучкості і нижчу вартість при масштабуванні для технічних користувачів."}]'::jsonb WHERE slug = 'zapier-ai' AND lang = 'ua';
UPDATE tools SET faq = '[{"q":"מה זה Zapier AI?","a":"Zapier AI הוא שכבת ה-AI בתוך Zapier המאפשרת יצירת זרימות עבודה אוטומטיות בשפה טבעית. תאר מה שאתה רוצה לאוטומט ו-Zapier AI ייצור את זרימת העבודה המחברת 7,000+ אפליקציות."},{"q":"כמה עולה Zapier?","a":"תוכנית חינמית עם 100 משימות לחודש ו-5 Zaps. Starter עולה $29.99 לחודש (750 משימות). Professional עולה $73.50 לחודש (2K משימות). Team עולה $103.50 לחודש. Enterprise במחיר מותאם."},{"q":"מה Zapier AI יכול לאוטומט?","a":"תגובות לדואר אלקטרוני, עדכוני CRM, פרסומים ברשתות חברתיות, הזנת נתונים, ניתוב לידים וכל משימה חוזרת ב-7,000+ אפליקציות מחוברות — מופעל על ידי אירועים או לפי לוח זמנים."},{"q":"במה Zapier AI שונה מ-n8n?","a":"Zapier הוא SaaS ללא קוד עם ספריית האינטגרציות הגדולה ביותר. n8n הוא קוד פתוח ומתארח בעצמו, ומציע גמישות רבה יותר ועלות נמוכה יותר בקנה מידה למשתמשים טכניים."}]'::jsonb WHERE slug = 'zapier-ai' AND lang = 'he';
UPDATE tools SET faq = '[{"q":"Qu''est-ce que Zapier AI ?","a":"Zapier AI est la couche IA de Zapier qui permet de créer des workflows automatisés en langage naturel. Décrivez ce que vous voulez automatiser et Zapier AI génère le workflow connectant plus de 7 000 applications."},{"q":"Combien coûte Zapier ?","a":"Plan gratuit avec 100 tâches/mois et 5 Zaps. Starter à $29.99/mois (750 tâches). Professional à $73.50/mois (2K tâches). Team à $103.50/mois. Enterprise sur devis."},{"q":"Que peut automatiser Zapier AI ?","a":"Réponses aux emails, mises à jour CRM, publications sur les réseaux sociaux, saisie de données, routage des leads et toute tâche répétitive dans 7 000+ applications connectées, déclenchée par des événements ou par planification."},{"q":"En quoi Zapier AI diffère-t-il de n8n ?","a":"Zapier est un SaaS sans code avec la plus grande bibliothèque d''intégrations. n8n est open-source et auto-hébergeable, offrant plus de flexibilité et un coût réduit à grande échelle pour les utilisateurs techniques."}]'::jsonb WHERE slug = 'zapier-ai' AND lang = 'fr';
UPDATE tools SET faq = '[{"q":"O que é o Zapier AI?","a":"O Zapier AI é a camada de IA dentro do Zapier que permite criar fluxos de trabalho automatizados em linguagem natural. Descreva o que quer automatizar e o Zapier AI gera o fluxo conectando mais de 7.000 apps."},{"q":"Quanto custa o Zapier?","a":"Plano gratuito com 100 tarefas/mês e 5 Zaps. Starter a $29.99/mês (750 tarefas). Professional a $73.50/mês (2K tarefas). Team a $103.50/mês. Enterprise sob consulta."},{"q":"O que o Zapier AI pode automatizar?","a":"Respostas de e-mail, atualizações de CRM, publicações em redes sociais, entrada de dados, roteamento de leads e qualquer tarefa repetitiva em mais de 7.000 apps conectados, acionada por eventos ou agendamento."},{"q":"Como o Zapier AI se diferencia do n8n?","a":"O Zapier é um SaaS sem código com a maior biblioteca de integrações. O n8n é open-source e auto-hospedável, oferecendo mais flexibilidade e custo menor em escala para usuários técnicos."}]'::jsonb WHERE slug = 'zapier-ai' AND lang = 'pt';

