INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, faq, published)
VALUES (
  'kiro', 'es', $$Kiro$$, $$https://kiro.dev$$, $$kiro.dev$$,
  'code', 'freemium', $$$$,
  $$IDE agéntico basado en especificaciones, implementación autónoma, Amazon AWS$$,
  $$Kiro es el entorno de desarrollo integrado agéntico basado en especificaciones de Amazon, anunciado en mayo de 2026 como reemplazo oficial del plugin Amazon Q Developer IDE. Los desarrolladores escriben Specs en lenguaje natural y Kiro genera autónomamente la implementación completa.$$,
  $$Kiro es el entorno de desarrollo integrado agéntico basado en especificaciones de Amazon, anunciado en mayo de 2026 como reemplazo oficial del plugin Amazon Q Developer IDE. Amazon bloqueó nuevas suscripciones al plugin Q Developer a partir del 15 de mayo de 2026, con soporte completo terminando el 30 de abril de 2027.

El concepto central de Kiro son los Specs. Un Spec es un documento en lenguaje natural que describe requisitos, decisiones de arquitectura y restricciones de implementación para una funcionalidad. En lugar de escribir código directamente, los desarrolladores escriben un Spec — Kiro lo lee y genera autónomamente la implementación completa: crea archivos, escribe funciones y conecta componentes.

Los Hooks son la capa de automatización orientada a eventos de Kiro. Se activan en eventos del sistema de archivos como guardar un archivo o hacer un commit, desencadenando acciones automatizadas del agente: ejecutar pruebas, verificar estilo o actualizar documentación al guardar; escanear seguridad o verificar que la implementación coincida con el Spec al hacer commit.

Kiro está construido como un IDE compatible con VS Code — las extensiones, atajos y configuraciones de workspace existentes funcionan sin migración. La capa agéntica se ejecuta en Amazon Bedrock con acceso a Claude, Amazon Nova y otros modelos. La integración profunda con AWS permite aprovisionar infraestructura y desplegar en AWS directamente desde el IDE.

Kiro está disponible en modo freemium. El nivel gratuito cubre desarrolladores individuales con uso limitado del agente. Los planes de pago están disponibles para equipos y empresas. Ideal para ingenieros y equipos en entornos AWS que quieren un agente que ejecute implementaciones completas desde requisitos estructurados.$$,
  ARRAY[$$Specs: escribir requisitos en lenguaje natural; Kiro construye autónomamente la implementación completa$$,$$Hooks: automatización orientada a eventos al guardar archivos y hacer commits — calidad integrada en el flujo$$,$$Basado en Amazon Bedrock con acceso a Claude, Amazon Nova y otros modelos de fundación$$,$$Compatible con VS Code — extensiones, atajos y configuraciones de workspace funcionan sin migración$$,$$Integración profunda con AWS: aprovisionar infraestructura y desplegar en AWS directamente desde el IDE$$],
  ARRAY[$$El flujo basado en Specs requiere escribir requisitos previamente — sobrecarga para tareas pequeñas$$,$$Producto nuevo que reemplaza Amazon Q Developer — ecosistema más pequeño que Cursor$$,$$La calidad del agente en Specs complejos aún se está comprobando en entornos de producción$$,$$Más adecuado para cargas de trabajo centradas en AWS — menos valor para otros proveedores de nube$$],
  $$[{"q":"¿Qué es Kiro?","a":"Kiro es el IDE agéntico basado en especificaciones de Amazon, lanzado en mayo de 2026 como reemplazo del plugin Amazon Q Developer IDE. Los desarrolladores escriben Specs en lenguaje natural describiendo qué construir, y Kiro genera autónomamente la implementación completa."},{"q":"¿Cuánto cuesta Kiro?","a":"Kiro está disponible en modo freemium. El nivel gratuito cubre desarrolladores individuales con uso limitado del agente. Los planes de pago para equipos y empresas están disponibles en kiro.dev."},{"q":"¿Qué son los Kiro Specs?","a":"Los Specs son documentos en lenguaje natural que describen requisitos y restricciones de implementación para una funcionalidad. Kiro lee el Spec y genera autónomamente código, archivos y arquitectura — conectando los requisitos de negocio con la implementación."},{"q":"¿Qué son los Kiro Hooks?","a":"Los Hooks son automatizaciones orientadas a eventos que se activan en acciones del desarrollador como guardar un archivo o hacer un commit. Pueden ejecutar pruebas automáticamente, actualizar documentación o lanzar análisis de seguridad — integrando controles de calidad en el flujo de desarrollo."}]$$::jsonb,
  true
)
