INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, faq, published)
VALUES (
  'kiro', 'de', $$Kiro$$, $$https://kiro.dev$$, $$kiro.dev$$,
  'code', 'freemium', $$$$,
  $$Spec-getriebene agentische IDE, autonome Implementierung, Amazon AWS$$,
  $$Kiro ist Amazons spec-getriebene agentische integrierte Entwicklungsumgebung, angekündigt im Mai 2026 als offizieller Ersatz für das Amazon Q Developer IDE-Plugin. Entwickler schreiben Specs in natürlicher Sprache — Kiro generiert autonom die vollständige Implementierung.$$,
  $$Kiro ist Amazons spec-getriebene agentische integrierte Entwicklungsumgebung, angekündigt im Mai 2026 als offizieller Ersatz für das Amazon Q Developer IDE-Plugin. Amazon hat neue Anmeldungen für das Q Developer IDE-Plugin ab dem 15. Mai 2026 blockiert, mit vollem Plugin-Support-Ende am 30. April 2027.

Das Kernkonzept in Kiro sind Specs. Ein Spec ist ein Dokument in natürlicher Sprache, das Anforderungen, Architekturentscheidungen und Implementierungseinschränkungen für ein Feature beschreibt. Anstatt Code direkt zu schreiben, schreibt der Entwickler einen Spec — Kiro liest ihn und generiert autonom die vollständige Implementierung: erstellt Dateien, schreibt Funktionen und verbindet Komponenten.

Hooks sind Kiros ereignisgesteuerter Automatisierungslayer. Hooks feuern bei Dateisystem-Ereignissen wie Datei-Speichern oder Git-Commit und lösen automatisierte Agenten-Aktionen aus: Tests ausführen, Linting oder Dokumentation aktualisieren beim Speichern; Sicherheitsscans, Changelog-Updates oder Spec-Abgleich beim Commit.

Kiro ist als VS Code-kompatible IDE gebaut — bestehende VS Code-Erweiterungen, Tastenbelegungen und Workspace-Konfigurationen funktionieren ohne Migration. Der Agenten-Layer läuft auf Amazon Bedrock mit Zugriff auf Claude, Amazon Nova und andere Foundation Models. Tiefe AWS-Integration ermöglicht Infrastruktur-Provisionierung und Deployment direkt aus der IDE.

Kiro ist als Freemium verfügbar. Die kostenlose Stufe unterstützt einzelne Entwickler mit begrenzter Agenten-Nutzung. Kostenpflichtige Stufen für Teams und Unternehmen sind verfügbar. Ideal für Software-Ingenieure und Teams in AWS-zentrierten Umgebungen.$$,
  ARRAY[$$Specs: Anforderungen in natürlicher Sprache schreiben; Kiro baut autonom die vollständige Implementierung$$,$$Hooks: ereignisgesteuerte Automatisierung bei Datei-Speichern und Git-Commit — eingebettete Qualitätsgates$$,$$Basiert auf Amazon Bedrock mit Zugriff auf Claude, Amazon Nova und andere Foundation Models$$,$$VS Code-kompatibel — bestehende Erweiterungen, Tastenbelegungen und Workspace-Konfigurationen funktionieren ohne Migration$$,$$Tiefe AWS-Integration: Infrastruktur bereitstellen und direkt aus der IDE in AWS deployen$$],
  ARRAY[$$Spec-getriebener Workflow erfordert vorheriges Anforderungsschreiben — Overhead für kleine Aufgaben$$,$$Neues Produkt, das Amazon Q Developer ersetzt — kleinere Ökosystem-Reife als Cursor$$,$$Agenten-Qualität bei komplexen Specs wird noch in Produktionsumgebungen bewiesen$$,$$Am besten für AWS-zentrierte Workloads geeignet — weniger Wert für Teams bei anderen Cloud-Anbietern$$],
  $$[{"q":"Was ist Kiro?","a":"Kiro ist Amazons spec-getriebene agentische IDE, die im Mai 2026 als Ersatz für das Amazon Q Developer IDE-Plugin gestartet ist. Entwickler schreiben Specs in natürlicher Sprache, die beschreiben was gebaut werden soll, und Kiro generiert autonom die vollständige Implementierung."},{"q":"Was kostet Kiro?","a":"Kiro ist als Freemium verfügbar. Eine kostenlose Stufe deckt einzelne Entwickler mit begrenzter Agenten-Nutzung ab. Kostenpflichtige Stufen für Teams und Unternehmen sind auf kiro.dev verfügbar."},{"q":"Was sind Kiro Specs?","a":"Specs sind Dokumente in natürlicher Sprache, die Anforderungen und Implementierungseinschränkungen für ein Feature beschreiben. Kiro liest den Spec und generiert autonom Code, Dateien und Architektur — und überbrückt damit Geschäftsanforderungen und Implementierung."},{"q":"Was sind Kiro Hooks?","a":"Hooks sind ereignisgesteuerte Automatisierungen, die bei Entwickleraktionen wie Datei-Speichern oder Git-Commit ausgelöst werden. Sie können automatisch Tests ausführen, Dokumentation aktualisieren oder Sicherheitsscans starten — und betten Qualitätsgates direkt in den Entwicklungsworkflow ein."}]$$::jsonb,
  true
)
