INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, faq, published)
VALUES (
  'kiro', 'ua', $$Kiro$$, $$https://kiro.dev$$, $$kiro.dev$$,
  'code', 'freemium', $$$$,
  $$Spec-driven агентна IDE, автономна реалізація, Amazon AWS$$,
  $$Kiro — агентна IDE Amazon на базі специфікацій, оголошена в травні 2026 як офіційна заміна плагіну Amazon Q Developer IDE. Розробники пишуть Specs природною мовою — Kiro автономно генерує повну реалізацію.$$,
  $$Kiro — агентна IDE Amazon на базі специфікацій, оголошена в травні 2026 як офіційна заміна плагіну Amazon Q Developer IDE. Amazon заблокував нові реєстрації на плагін Q Developer з 15 травня 2026, повна підтримка плагіну завершиться 30 квітня 2027.

Ключова концепція — Specs. Spec — документ природною мовою, що описує вимоги, архітектурні рішення та обмеження реалізації для функції або компонента. Замість написання коду розробник пише Spec — Kiro читає його й автономно генерує повну реалізацію: створює файли, пише функції, обробляє граничні випадки та з'єднує компоненти.

Hooks — подієвий шар автоматизації Kiro. Hooks спрацьовують при подіях файлової системи (збереження файлу, git commit) і запускають дії агента. При збереженні — тести, лінтинг або оновлення документації. При коміті — сканування безпеки, оновлення changelog або перевірка відповідності реалізації Spec.

Kiro побудований як IDE сумісна з VS Code — наявні розширення, комбінації клавіш і конфігурації робочого простору працюють без міграції. Агентний шар працює на Amazon Bedrock з доступом до Claude, Amazon Nova та інших моделей. Глибока інтеграція з AWS дозволяє провізіонувати інфраструктуру та деплоїти в AWS прямо з IDE.

Kiro доступний за моделлю freemium. Безкоштовний тариф підтримує індивідуальних розробників з обмеженим використанням агента. Платні тарифи для команд та підприємств доступні на kiro.dev.$$,
  ARRAY[$$Specs: написання вимог природною мовою — Kiro автономно будує повну реалізацію$$,$$Hooks: подієва автоматизація при збереженні файлу та git commit — вбудовані перевірки якості$$,$$Працює на Amazon Bedrock з доступом до Claude, Amazon Nova та інших моделей$$,$$Сумісний з VS Code — наявні розширення, клавіші та конфіги працюють без міграції$$,$$Глибока інтеграція з AWS: провізіонування інфраструктури та деплой прямо з IDE$$],
  ARRAY[$$Spec-driven підхід вимагає попереднього написання вимог — зайве навантаження для малих задач$$,$$Новий продукт, що замінює Amazon Q Developer — екосистема менша, ніж у Cursor$$,$$Якість агента на складних Specs ще перевіряється у виробничих умовах$$,$$Найкраще підходить для AWS-оточень — менша цінність для інших хмарних провайдерів$$],
  $$[{"q":"Що таке Kiro?","a":"Kiro — агентна IDE Amazon на базі специфікацій, запущена у травні 2026 як заміна плагіну Amazon Q Developer IDE. Розробники пишуть Specs природною мовою, описуючи що потрібно побудувати, а Kiro автономно генерує повну реалізацію."},{"q":"Скільки коштує Kiro?","a":"Kiro доступний за моделлю freemium. Безкоштовний тариф для індивідуальних розробників з обмеженим використанням агента. Платні тарифи для команд та підприємств доступні на kiro.dev."},{"q":"Що таке Kiro Specs?","a":"Specs — документи природною мовою, що описують вимоги та обмеження реалізації для функції. Kiro читає Spec і автономно генерує код, файли та архітектуру — поєднуючи бізнес-вимоги з реалізацією."},{"q":"Що таке Kiro Hooks?","a":"Hooks — подієві автоматизації, що спрацьовують при діях розробника: збереженні файлу або git commit. Вони можуть автоматично запускати тести, оновлювати документацію або запускати сканування безпеки — вбудовуючи перевірки якості безпосередньо у робочий процес."}]$$::jsonb,
  true
)
