INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, faq, published)
VALUES (
  'kiro', 'he', $$Kiro$$, $$https://kiro.dev$$, $$kiro.dev$$,
  'code', 'freemium', $$$$,
  $$IDE אגנטי מבוסס-Spec, יישום אוטונומי, Amazon AWS$$,
  $$Kiro הוא סביבת הפיתוח האגנטית המבוססת-Spec של Amazon, שהוכרזה במאי 2026 כתחליף הרשמי לתוסף Amazon Q Developer IDE. מפתחים כותבים Specs בשפה טבעית — Kiro מייצר את היישום המלא באופן אוטונומי.$$,
  $$Kiro הוא סביבת הפיתוח האגנטית המבוססת-Spec של Amazon, שהוכרזה במאי 2026 כתחליף הרשמי לתוסף Amazon Q Developer IDE. Amazon חסם רשומות חדשות לתוסף Q Developer IDE מה-15 במאי 2026, עם סיום התמיכה המלאה ב-30 באפריל 2027.

המושג המרכזי ב-Kiro הוא Specs. Spec הוא מסמך בשפה טבעית המתאר דרישות, החלטות ארכיטקטורה ואילוצי יישום עבור תכונה. במקום לכתוב קוד ישירות, המפתח כותב Spec — Kiro קורא אותו ומייצר את היישום המלא באופן אוטונומי: יוצר קבצים, כותב פונקציות ומחבר רכיבים.

Hooks הם שכבת האוטומציה מבוססת-האירועים של Kiro. Hooks מופעלים על ידי אירועי מערכת קבצים כמו שמירת קובץ או git commit ומפעילים פעולות אגנטיות אוטומטיות: הרצת בדיקות, linting או עדכון תיעוד בעת שמירה; סריקת אבטחה, עדכון changelog או אימות שהיישום עדיין תואם את ה-Spec בעת commit.

Kiro בנוי כ-IDE תואם VS Code — תוספי VS Code, קיצורי מקלדת וקונפיגורציות workspace קיימים עובדים ללא הגירה. שכבת האגנט פועלת על Amazon Bedrock עם גישה ל-Claude, Amazon Nova ומודלים נוספים. האינטגרציה העמוקה עם AWS מאפשרת פרוביז'ן תשתית ופריסה לסביבות AWS ישירות מה-IDE.

Kiro זמין בגרסת freemium. רמה חינמית תומכת במפתחים בודדים עם שימוש מוגבל באגנט. רמות בתשלום לצוותים ולארגונים זמינות ב-kiro.dev.$$,
  ARRAY[$$Specs: כתיבת דרישות בשפה טבעית; Kiro בונה באופן אוטונומי את היישום המלא$$,$$Hooks: אוטומציה מבוססת-אירועים בשמירת קובץ ו-git commit — שערי איכות מובנים$$,$$בנוי על Amazon Bedrock עם גישה ל-Claude, Amazon Nova ומודלי בסיס נוספים$$,$$תואם VS Code — תוספים, קיצורי מקלדת וקונפיגורציות workspace קיימים עובדים ללא הגירה$$,$$אינטגרציה עמוקה עם AWS: פרוביז'ן תשתית ופריסה לסביבות AWS ישירות מה-IDE$$],
  ARRAY[$$תהליך מבוסס-Spec דורש כתיבת דרישות מוקדמת — עומס נוסף למשימות קטנות וזריזות$$,$$מוצר חדש המחליף את Amazon Q Developer — בשלות אקוסיסטם קטנה יותר מ-Cursor$$,$$איכות האגנט ב-Specs מורכבים עדיין נבחנת בסביבות ייצור$$,$$מתאים ביותר לעומסי עבודה ממוקדי AWS — פחות ערך לצוותים אצל ספקי ענן אחרים$$],
  $$[{"q":"מה זה Kiro?","a":"Kiro הוא ה-IDE האגנטי המבוסס-Spec של Amazon, שהושק במאי 2026 כתחליף לתוסף Amazon Q Developer IDE. מפתחים כותבים Specs בשפה טבעית המתארים מה לבנות, ו-Kiro מייצר את היישום המלא באופן אוטונומי."},{"q":"כמה עולה Kiro?","a":"Kiro זמין בגרסת freemium. רמה חינמית מכסה מפתחים בודדים עם שימוש מוגבל באגנט. רמות בתשלום לצוותים ולארגונים זמינות ב-kiro.dev."},{"q":"מה הם Kiro Specs?","a":"Specs הם מסמכים בשפה טבעית המתארים דרישות ואילוצי יישום עבור תכונה. Kiro קורא את ה-Spec ומייצר באופן אוטונומי קוד, קבצים וארכיטקטורה — גישור על פער הדרישות העסקיות והיישום."},{"q":"מה הם Kiro Hooks?","a":"Hooks הם אוטומציות מבוססות-אירועים המופעלות על ידי פעולות מפתח כמו שמירת קובץ או git commit. הן יכולות להריץ אוטומטית בדיקות, לעדכן תיעוד או להפעיל סריקות אבטחה — ומטמיעות שערי איכות ישירות בתהליך הפיתוח."}]$$::jsonb,
  true
)
