INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, faq, published)
VALUES (
  'kiro', 'fr', $$Kiro$$, $$https://kiro.dev$$, $$kiro.dev$$,
  'code', 'freemium', $$$$,
  $$IDE agentique basé sur des Specs, implémentation autonome, Amazon AWS$$,
  $$Kiro est l'environnement de développement intégré agentique basé sur des spécifications d'Amazon, annoncé en mai 2026 comme remplacement officiel du plugin Amazon Q Developer IDE. Les développeurs écrivent des Specs en langage naturel — Kiro génère automatiquement l'implémentation complète.$$,
  $$Kiro est l'environnement de développement intégré agentique basé sur des spécifications d'Amazon, annoncé en mai 2026 comme remplacement officiel du plugin Amazon Q Developer IDE. Amazon a bloqué les nouvelles inscriptions au plugin Q Developer à partir du 15 mai 2026, avec la fin du support complet le 30 avril 2027.

Le concept central de Kiro est les Specs. Un Spec est un document en langage naturel décrivant les exigences, les décisions d'architecture et les contraintes d'implémentation pour une fonctionnalité. Au lieu d'écrire du code directement, le développeur écrit un Spec — Kiro le lit et génère automatiquement l'implémentation complète : crée les fichiers, écrit les fonctions et connecte les composants.

Les Hooks constituent la couche d'automatisation événementielle de Kiro. Les Hooks se déclenchent sur des événements du système de fichiers comme la sauvegarde d'un fichier ou un git commit, lançant des actions automatisées de l'agent : exécuter des tests, vérifier le style ou mettre à jour la documentation lors de la sauvegarde ; scanner la sécurité ou vérifier l'alignement Spec lors du commit.

Kiro est construit comme un IDE compatible VS Code — les extensions, raccourcis clavier et configurations de workspace existants fonctionnent sans migration. La couche agentique tourne sur Amazon Bedrock avec accès à Claude, Amazon Nova et d'autres modèles. L'intégration profonde avec AWS permet de provisionner l'infrastructure et de déployer dans AWS directement depuis l'IDE.

Kiro est disponible en freemium. Le niveau gratuit couvre les développeurs individuels avec une utilisation limitée de l'agent. Des plans payants pour les équipes et les entreprises sont disponibles sur kiro.dev.$$,
  ARRAY[$$Specs : écrire des exigences en langage naturel ; Kiro construit automatiquement l'implémentation complète$$,$$Hooks : automatisation événementielle à la sauvegarde de fichier et au git commit — contrôles qualité intégrés$$,$$Construit sur Amazon Bedrock avec accès à Claude, Amazon Nova et d'autres modèles de fondation$$,$$Compatible VS Code — les extensions, raccourcis et configurations de workspace existants fonctionnent sans migration$$,$$Intégration profonde AWS : provisionner l'infrastructure et déployer dans AWS directement depuis l'IDE$$],
  ARRAY[$$Le workflow basé sur Specs nécessite d'écrire les exigences en amont — surcharge pour les petites tâches$$,$$Nouveau produit remplaçant Amazon Q Developer — maturité d'écosystème plus faible que Cursor$$,$$La qualité de l'agent sur des Specs complexes est encore en cours de validation en production$$,$$Mieux adapté aux charges de travail AWS — moins de valeur pour les équipes sur d'autres fournisseurs cloud$$],
  $$[{"q":"Qu'est-ce que Kiro ?","a":"Kiro est l'IDE agentique basé sur des spécifications d'Amazon, lancé en mai 2026 comme remplacement du plugin Amazon Q Developer IDE. Les développeurs écrivent des Specs en langage naturel décrivant ce qu'ils veulent construire, et Kiro génère automatiquement l'implémentation complète."},{"q":"Combien coûte Kiro ?","a":"Kiro est disponible en freemium. Un niveau gratuit couvre les développeurs individuels avec une utilisation limitée de l'agent. Des plans payants pour les équipes et les entreprises sont disponibles sur kiro.dev."},{"q":"Que sont les Kiro Specs ?","a":"Les Specs sont des documents en langage naturel décrivant les exigences et les contraintes d'implémentation pour une fonctionnalité. Kiro lit le Spec et génère automatiquement du code, des fichiers et une architecture — faisant le pont entre les exigences métier et l'implémentation."},{"q":"Que sont les Kiro Hooks ?","a":"Les Hooks sont des automatisations événementielles qui se déclenchent sur des actions du développeur comme la sauvegarde d'un fichier ou un git commit. Ils peuvent exécuter automatiquement des tests, mettre à jour la documentation ou lancer des scans de sécurité — intégrant des contrôles qualité directement dans le workflow de développement."}]$$::jsonb,
  true
)
