INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, faq, published)
VALUES (
  'kiro', 'pt', $$Kiro$$, $$https://kiro.dev$$, $$kiro.dev$$,
  'code', 'freemium', $$$$,
  $$IDE agêntico baseado em Specs, implementação autônoma, Amazon AWS$$,
  $$Kiro é o ambiente de desenvolvimento integrado agêntico baseado em especificações da Amazon, anunciado em maio de 2026 como substituto oficial do plugin Amazon Q Developer IDE. Os desenvolvedores escrevem Specs em linguagem natural — Kiro gera autonomamente a implementação completa.$$,
  $$Kiro é o ambiente de desenvolvimento integrado agêntico baseado em especificações da Amazon, anunciado em maio de 2026 como substituto oficial do plugin Amazon Q Developer IDE. A Amazon bloqueou novos cadastros no plugin Q Developer a partir de 15 de maio de 2026, com suporte total encerrando em 30 de abril de 2027.

O conceito central do Kiro são os Specs. Um Spec é um documento em linguagem natural que descreve requisitos, decisões de arquitetura e restrições de implementação para uma funcionalidade. Em vez de escrever código diretamente, o desenvolvedor escreve um Spec — Kiro o lê e gera autonomamente a implementação completa: cria arquivos, escreve funções e conecta componentes.

Os Hooks são a camada de automação orientada a eventos do Kiro. Os Hooks são acionados por eventos do sistema de arquivos como salvar um arquivo ou fazer um commit, disparando ações automatizadas do agente: executar testes, linting ou atualizar documentação ao salvar; escanear segurança ou verificar o alinhamento com o Spec ao fazer commit.

Kiro é construído como um IDE compatível com VS Code — extensões, atalhos de teclado e configurações de workspace existentes funcionam sem migração. A camada agêntica roda no Amazon Bedrock com acesso ao Claude, Amazon Nova e outros modelos. A integração profunda com AWS permite provisionar infraestrutura e fazer deploy para ambientes AWS diretamente da IDE.

Kiro está disponível como freemium. O nível gratuito cobre desenvolvedores individuais com uso limitado do agente. Planos pagos para equipes e empresas estão disponíveis em kiro.dev.$$,
  ARRAY[$$Specs: escrever requisitos em linguagem natural; Kiro constrói autonomamente a implementação completa$$,$$Hooks: automação orientada a eventos ao salvar arquivos e fazer commits — controles de qualidade integrados$$,$$Construído no Amazon Bedrock com acesso ao Claude, Amazon Nova e outros modelos de fundação$$,$$Compatível com VS Code — extensões, atalhos e configurações de workspace existentes funcionam sem migração$$,$$Integração profunda com AWS: provisionar infraestrutura e fazer deploy para AWS diretamente da IDE$$],
  ARRAY[$$Fluxo baseado em Specs exige escrita prévia de requisitos — sobrecarga para tarefas pequenas$$,$$Produto novo substituindo Amazon Q Developer — maturidade de ecossistema menor que Cursor$$,$$Qualidade do agente em Specs complexos ainda sendo comprovada em ambientes de produção$$,$$Mais adequado para cargas de trabalho centradas em AWS — menos valor para equipes em outros provedores$$],
  $$[{"q":"O que é o Kiro?","a":"Kiro é o IDE agêntico baseado em especificações da Amazon, lançado em maio de 2026 como substituto do plugin Amazon Q Developer IDE. Os desenvolvedores escrevem Specs em linguagem natural descrevendo o que querem construir, e Kiro gera autonomamente a implementação completa."},{"q":"Quanto custa o Kiro?","a":"Kiro está disponível como freemium. Um nível gratuito cobre desenvolvedores individuais com uso limitado do agente. Planos pagos para equipes e empresas estão disponíveis em kiro.dev."},{"q":"O que são os Kiro Specs?","a":"Specs são documentos em linguagem natural que descrevem requisitos e restrições de implementação para uma funcionalidade. Kiro lê o Spec e gera autonomamente código, arquivos e arquitetura — fazendo a ponte entre requisitos de negócio e implementação."},{"q":"O que são os Kiro Hooks?","a":"Hooks são automações orientadas a eventos que são acionadas em ações do desenvolvedor como salvar um arquivo ou fazer um commit. Eles podem executar testes automaticamente, atualizar documentação ou acionar varreduras de segurança — incorporando controles de qualidade diretamente no fluxo de desenvolvimento."}]$$::jsonb,
  true
)
